import React, { useCallback, useEffect, useState } from 'react';
import {
  Alert,
  CircularProgress,
  FormControlLabel,
  Switch,
  Typography,
} from '@mui/material';
import ApiService from '../../services/api';

interface ReviewSummary {
  scope: 'required' | 'all';
  ready: boolean;
  counts: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
    excluded: number;
  };
  open: {
    withoutCalculation: number;
    spendBased: number;
    calculated: number;
  };
  openRequired: number;
}

interface ConsultantReviewNoticeProps {
  context: 'csv' | 'report';
}

const ConsultantReviewNotice: React.FC<ConsultantReviewNoticeProps> = ({ context }) => {
  const [summary, setSummary] = useState<ReviewSummary | null>(null);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const load = useCallback(async () => {
    try {
      const response = await ApiService.getConsultantReview();
      const data = (response?.data || null) as ReviewSummary | null;
      if (data?.counts) setSummary(data);
    } catch {
      setSummary(null);
    }
  }, []);

  useEffect(() => {
    void load();
  }, [load]);

  const toggleScope = async (includeCalculated: boolean) => {
    setSaving(true);
    setError(null);
    try {
      const response = await ApiService.updateConsultantReviewScope(includeCalculated ? 'all' : 'required');
      const data = (response?.data || null) as ReviewSummary | null;
      if (data?.counts) setSummary(data);
    } catch (toggleError: unknown) {
      setError(toggleError instanceof Error ? toggleError.message : 'The review choice could not be saved.');
    } finally {
      setSaving(false);
    }
  };

  if (!summary) return null;

  const waiting = summary.open.withoutCalculation + summary.open.spendBased;
  const reportText = summary.ready
    ? 'The consultant has confirmed the rows that block the report. You can generate it.'
    : `The report stays blocked until the consultant confirms or corrects ${summary.openRequired} open transaction${summary.openRequired === 1 ? '' : 's'}. The transaction audit workbook can still be downloaded.`;

  return (
    <Alert severity={summary.ready ? 'success' : 'warning'} sx={{ mb: 1.5, alignItems: 'flex-start' }}>
      <Typography variant="body2">
        {`This company has ${summary.counts.withoutCalculation} transaction${summary.counts.withoutCalculation === 1 ? '' : 's'} without a calculation and ${summary.counts.spendBased} spend-based transaction${summary.counts.spendBased === 1 ? '' : 's'}. ${summary.counts.calculated} already have a calculation.`}
        {waiting > 0 ? ` ${waiting} of the without-calculation and spend-based rows are still open for the consultant.` : ' Those rows are already confirmed or corrected.'}
      </Typography>
      <Typography variant="body2" sx={{ mt: 0.5 }}>
        {context === 'report'
          ? reportText
          : 'These counts are for the whole company. The CSV for the current view repeats the same kind of counts for the rows in that file, then lists each transaction. The consultant reviews the without-calculation and spend-based rows before a report can be generated.'}
      </Typography>
      <FormControlLabel
        sx={{ mt: 0.5, ml: 0 }}
        control={(
          <Switch
            size="small"
            checked={summary.scope === 'all'}
            disabled={saving}
            onChange={(event) => { void toggleScope(event.target.checked); }}
            inputProps={{ 'aria-label': 'Also ask the consultant to review calculated transactions' }}
          />
        )}
        label="Also ask the consultant to review transactions that already have a calculation"
      />
      {saving ? <CircularProgress size={16} sx={{ ml: 1 }} /> : null}
      {error ? <Typography variant="body2" color="error">{error}</Typography> : null}
    </Alert>
  );
};

export default ConsultantReviewNotice;
