/**
 * Classifies a transaction for consultant review and decides whether a
 * statutory report may be generated.
 *
 * Required review: rows with no calculation, and spend-based rows.
 * Optional review: rows that already have an activity or supplier calculation,
 * when the company sets consultantReviewScope to "all".
 * A confirmation stays valid only while the calculation fingerprint matches.
 */

const REVIEW_STATUSES = new Set(['confirmed', 'corrected']);

const flagText = (flags) => {
  if (Array.isArray(flags)) return flags.filter(Boolean).join(';');
  if (flags && typeof flags === 'object') {
    return Object.entries(flags)
      .filter(([, on]) => Boolean(on))
      .map(([key]) => key)
      .join(';');
  }
  return String(flags || '');
};

const calculationView = (transaction = {}) => {
  const footprint = transaction.carbonFootprint && typeof transaction.carbonFootprint === 'object'
    ? transaction.carbonFootprint
    : transaction;
  const record = footprint.calculationRecord || {};
  const review = transaction.metadata?.consultantReview || transaction.consultantReview || null;
  return {
    quantificationMethod: footprint.quantificationMethod || footprint.calculationMethod || '',
    dataQualityTier: footprint.dataQualityTier || '',
    formula: record.formula || footprint.formula || '',
    complianceFlags: footprint.complianceFlags,
    exclusionReason: footprint.exclusionReason || transaction.exclusionReason || '',
    factorId: footprint.factorLineage?.id || footprint.factorId || '',
    co2Emissions: Number(footprint.co2Emissions || 0),
    category: transaction.category || '',
    quantity: transaction.quantity,
    unit: transaction.unit || '',
    consultantReview: review,
    isSpam: transaction.isSpam === true,
    isDuplicate: transaction.isDuplicate === true
  };
};

const classifyCalculation = (transaction) => {
  const view = calculationView(transaction);
  if (view.isSpam || view.isDuplicate) return 'excluded';

  const method = String(view.quantificationMethod).toLowerCase();
  const tier = String(view.dataQualityTier).toLowerCase();
  const formula = String(view.formula);
  const flags = flagText(view.complianceFlags);
  const factorId = String(view.factorId);

  if (method.includes('supplier')) return 'calculated';
  if (method.includes('excluded') || tier === 'excluded' || view.exclusionReason) return 'excluded';

  const needsExpert = method.includes('admin_emission_review')
    || formula === 'adminEmissionReview'
    || flags.includes('admin_emission_review_required');
  const missingActivity = method.includes('needs_activity')
    || /_missing\b/i.test(flags)
    || /_missing\b/i.test(factorId);
  const notStated = !method && !formula && !tier;
  const spend = method.includes('spend') || tier.includes('tier_2') || formula.includes('spendAmount');
  const activity = method.includes('activity')
    || formula.startsWith('activityQuantity')
    || tier.includes('tier_1');

  if (needsExpert || missingActivity || notStated) return 'without_calculation';
  if (spend) return 'spend_based';
  if (activity) return 'calculated';
  return 'without_calculation';
};

const CALCULATION_CLASS_LABELS = {
  without_calculation: 'Without calculation',
  spend_based: 'Spend-based',
  calculated: 'With calculation',
  excluded: 'Excluded'
};

const calculationClassLabel = (calculationClass) => (
  CALCULATION_CLASS_LABELS[calculationClass] || 'Without calculation'
);

const calculationFingerprint = (transaction) => {
  const view = calculationView(transaction);
  const calculationClass = classifyCalculation(transaction);
  const quantity = view.quantity == null || view.quantity === '' ? '' : String(view.quantity);
  const co2 = Number.isFinite(view.co2Emissions) ? view.co2Emissions.toFixed(4) : '0.0000';
  return [
    calculationClass,
    view.quantificationMethod,
    view.formula,
    co2,
    view.category,
    quantity,
    view.unit
  ].join('|');
};

const reviewIsCurrent = (transaction) => {
  const review = calculationView(transaction).consultantReview;
  if (!review || !REVIEW_STATUSES.has(String(review.status || ''))) return false;
  return String(review.fingerprint || '') === calculationFingerprint(transaction);
};

const emptyCounts = () => ({
  withoutCalculation: 0,
  spendBased: 0,
  calculated: 0,
  excluded: 0
});

const normalizeScope = (scope) => (scope === 'all' ? 'all' : 'required');

const summarizeConsultantReview = (transactions, scope = 'required') => {
  const counts = emptyCounts();
  const open = {
    withoutCalculation: 0,
    spendBased: 0,
    calculated: 0
  };

  (transactions || []).forEach((transaction) => {
    const calculationClass = classifyCalculation(transaction);
    if (calculationClass === 'excluded') {
      counts.excluded += 1;
      return;
    }
    if (calculationClass === 'spend_based') counts.spendBased += 1;
    else if (calculationClass === 'calculated') counts.calculated += 1;
    else counts.withoutCalculation += 1;

    if (reviewIsCurrent(transaction)) return;
    if (calculationClass === 'spend_based') open.spendBased += 1;
    else if (calculationClass === 'calculated') open.calculated += 1;
    else open.withoutCalculation += 1;
  });

  const normalizedScope = normalizeScope(scope);
  const openRequired = open.withoutCalculation
    + open.spendBased
    + (normalizedScope === 'all' ? open.calculated : 0);

  return {
    scope: normalizedScope,
    counts,
    open,
    openRequired,
    ready: openRequired === 0
  };
};

const blocksReport = (calculationClass, scope) => {
  if (calculationClass === 'excluded') return false;
  if (calculationClass === 'calculated') return normalizeScope(scope) === 'all';
  return calculationClass === 'without_calculation' || calculationClass === 'spend_based';
};

const csvSummaryLines = (summary) => ([
  'Consultant review summary',
  `Without calculation,${summary.counts.withoutCalculation}`,
  `Spend-based,${summary.counts.spendBased}`,
  `With calculation,${summary.counts.calculated}`,
  `Excluded,${summary.counts.excluded}`,
  `Still open without calculation,${summary.open.withoutCalculation}`,
  `Still open spend-based,${summary.open.spendBased}`,
  `Still open with calculation,${summary.open.calculated}`,
  ''
]);

const blockMessage = (summary) => {
  const parts = [];
  if (summary.open.withoutCalculation) {
    parts.push(`${summary.open.withoutCalculation} without a calculation`);
  }
  if (summary.open.spendBased) {
    parts.push(`${summary.open.spendBased} spend-based`);
  }
  if (summary.scope === 'all' && summary.open.calculated) {
    parts.push(`${summary.open.calculated} with a calculation`);
  }
  const list = parts.length ? parts.join(', ') : 'the open rows';
  return `An expert consultant still has to review ${list} before this report can be generated.`;
};

module.exports = {
  CALCULATION_CLASS_LABELS,
  blockMessage,
  blocksReport,
  calculationClassLabel,
  calculationFingerprint,
  classifyCalculation,
  csvSummaryLines,
  reviewIsCurrent,
  summarizeConsultantReview
};
