import React, { useEffect, useMemo, useRef, useState } from 'react';
import {
  Alert,
  Box,
  Button,
  Checkbox,
  Chip,
  FormControl,
  FormControlLabel,
  FormGroup,
  FormHelperText,
  InputLabel,
  MenuItem,
  Paper,
  Select,
  Stack,
  TextField,
  Typography,
} from '@mui/material';
import { alpha, useTheme } from '@mui/material/styles';
import { formatImportAmount, formatImportDate } from '../connectors/accountingImportResult';
import {
  type ClarificationAnswerDraft,
  type ClarificationField,
  type ClarificationQueueItem,
  buildClarificationAnswer,
  clarificationProgress,
  groupClarificationItems,
  initialClarificationDraft,
  quantitiesDiffer,
  showFreeText,
  validateClarificationGroup,
  visibleClarificationFields,
} from './clarificationModel';

export interface ClarificationSubmission {
  item: ClarificationQueueItem;
  body: ReturnType<typeof buildClarificationAnswer>;
}

interface ClarificationQueueProps {
  items: ClarificationQueueItem[];
  loading?: boolean;
  saving?: boolean;
  resetToken?: number;
  preferredKey?: string | null;
  completedGroupCount?: number;
  totalGroupCount?: number;
  ordinalByKey?: Record<string, number>;
  onSubmitGroup: (entries: ClarificationSubmission[]) => void;
}

const presentText = (value: unknown) => {
  const text = String(value ?? '').trim();
  return text || '';
};

const sameText = (left: string, right: string) => left.trim().toLowerCase() === right.trim().toLowerCase();

const SENSITIVE_HEADER = /gstin|gst[\s._-]*no|taxpayer|\bpan\b|aadhaar|aadhar|\bphone\b|\bmobile\b|e-?mail|\bbank\b|\bifsc\b|account[\s._-]*(no|number|#)|password|credential|secret|\bupi\b|card[\s._-]*(no|number)/i;

const sensitiveValue = (value: string) => {
  if (/\b\d{2}[A-Z]{5}\d{4}[A-Z][A-Z0-9]Z[A-Z0-9]\b/i.test(value)) return true;
  if (/\b[A-Z]{5}\d{4}[A-Z]\b/i.test(value)) return true;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value)) return true;
  return /^\d{10,18}$/.test(value.replace(/[\s-]/g, ''));
};

const pushFact = (
  facts: Array<{ label: string; value: string }>,
  label: string,
  value: string
) => {
  if (!value || facts.some((fact) => sameText(fact.value, value))) return;
  facts.push({ label, value });
};

const contextFacts = (
  item: ClarificationQueueItem,
  options: { includeFile?: boolean; includeSourceCells?: boolean } = {}
) => {
  const includeFile = options.includeFile !== false;
  const includeSourceCells = options.includeSourceCells !== false;
  const facts: Array<{ label: string; value: string }> = [];
  const description = presentText(item.description);
  if (description && !item.agentMessage?.includes(description)) {
    pushFact(facts, 'Description', description);
  }
  const party = presentText(item.vendorName);
  if (party && !/^unknown vendor$/i.test(party)) pushFact(facts, 'Party', party);
  pushFact(facts, 'Item', presentText(item.itemName));
  pushFact(facts, 'Ledger', presentText(item.ledgerName));
  pushFact(facts, 'Voucher type', presentText(item.voucherType));
  if (item.amount != null && Number.isFinite(Number(item.amount))) {
    pushFact(facts, 'Amount', formatImportAmount(item.amount));
  }
  if (item.date != null && item.date !== '') {
    const formatted = formatImportDate(item.date);
    if (formatted && formatted !== '—') pushFact(facts, 'Date', formatted);
  }
  const sheetRow = Number(item.sourceContext?.sheetRow);
  if (Number.isInteger(sheetRow) && sheetRow > 1) {
    facts.push({ label: 'Worksheet row', value: String(sheetRow) });
  } else if (item.rowIndex != null && Number.isFinite(Number(item.rowIndex))) {
    facts.push({ label: 'Source row', value: String(item.rowIndex) });
  }
  pushFact(facts, 'Category', presentText(item.category));
  pushFact(facts, 'Subcategory', presentText(item.subcategory));
  const quantity = [presentText(item.quantity), presentText(item.unit)].filter(Boolean).join(' ');
  pushFact(facts, 'Quantity', quantity);
  if (includeFile) pushFact(facts, 'File', presentText(item.importFileName));
  const reference = presentText(item.sourceId);
  if (reference && reference !== item.transactionId) pushFact(facts, 'Reference', reference);
  if (includeSourceCells) {
    (item.sourceContext?.cells || []).forEach((cell) => {
      const header = presentText(cell.header);
      const value = presentText(cell.value);
      if (!header || !value || SENSITIVE_HEADER.test(header) || sensitiveValue(value)) return;
      const existing = facts.find((fact) => sameText(fact.value, value));
      if (existing) {
        if (['Ledger', 'Item', 'Voucher type'].includes(existing.label)) existing.label = header;
        return;
      }
      pushFact(facts, header, value);
    });
  }
  return facts;
};

const voucherLabel = (item: ClarificationQueueItem) => {
  const facts = contextFacts(
    { ...item, description: undefined, agentMessage: undefined },
    { includeFile: false }
  );
  return [presentText(item.description) || 'Voucher', ...facts.map((fact) => fact.value)]
    .filter(Boolean)
    .join(' · ');
};

const ContextFacts: React.FC<{ item: ClarificationQueueItem }> = ({ item }) => {
  const facts = contextFacts(item);
  if (facts.length === 0) return null;
  return (
    <Box
      component="dl"
      aria-label="Imported transaction"
      sx={{
        display: 'grid',
        gridTemplateColumns: { xs: '1fr', sm: '1fr 1fr' },
        gap: 1.25,
        m: 0,
      }}
    >
      {facts.map((fact, index) => (
        <Box key={`${fact.label}-${index}`} sx={{ minWidth: 0 }}>
          <Typography component="dt" variant="caption" color="text.secondary">
            {fact.label}
          </Typography>
          <Typography component="dd" variant="body2" sx={{ m: 0, fontWeight: 600, wordBreak: 'break-word' }}>
            {fact.value}
          </Typography>
        </Box>
      ))}
    </Box>
  );
};

const ClarificationQueue: React.FC<ClarificationQueueProps> = ({
  items,
  loading = false,
  saving = false,
  resetToken = 0,
  preferredKey = null,
  completedGroupCount,
  totalGroupCount,
  ordinalByKey,
  onSubmitGroup,
}) => {
  const theme = useTheme();
  const groups = useMemo(() => groupClarificationItems(items), [items]);
  const [drafts, setDrafts] = useState<Record<string, ClarificationAnswerDraft>>({});
  const [selectedByGroup, setSelectedByGroup] = useState<Record<string, string[]>>({});
  const [activeKey, setActiveKey] = useState<string | null>(null);
  const [errors, setErrors] = useState<Record<string, string>>({});
  const baseline = useRef<Set<string> | null>(null);
  const preferredStamp = useRef<string | null>(null);

  useEffect(() => {
    baseline.current = null;
    setErrors({});
  }, [resetToken]);

  if (preferredKey && preferredStamp.current !== preferredKey) {
    preferredStamp.current = preferredKey;
    if (activeKey !== preferredKey) setActiveKey(preferredKey);
  }

  if (!loading && baseline.current === null) {
    baseline.current = new Set(groups.map((group) => group.key));
  }

  const sessionCompleted = baseline.current
    ? Array.from(baseline.current).filter((key) => !groups.some((group) => group.key === key)).length
    : 0;
  const completedGroups = typeof completedGroupCount === 'number' ? completedGroupCount : sessionCompleted;
  const progressTotal = typeof totalGroupCount === 'number' && typeof completedGroupCount === 'number'
    ? Math.max(groups.length, totalGroupCount - completedGroupCount)
    : groups.length;

  const current = groups.find((group) => group.key === (activeKey || preferredKey)) || groups[0];
  const draft = current ? (drafts[current.key] || initialClarificationDraft(current)) : null;
  const selectedIds = new Set(
    current
      ? (selectedByGroup[current.key] || current.items.map((item) => item.transactionId))
      : []
  );

  if (loading) {
    return <Typography variant="body2">The agent is reviewing quantities and units.</Typography>;
  }
  if (!current || !draft) return null;

  const template = current.items[0];
  const fields = visibleClarificationFields(template, draft);
  const selectedItems = current.items.filter((item) => selectedIds.has(item.transactionId));
  const progress = clarificationProgress(completedGroups, progressTotal, items.length);
  const stepIndex = Math.max(0, groups.findIndex((group) => group.key === current.key));
  const stepNumber = ordinalByKey?.[current.key] ?? (stepIndex + 1);
  const stepTotal = typeof totalGroupCount === 'number' ? totalGroupCount : groups.length;
  const saveLabel = groups.length > 1 ? 'Save and next group' : 'Save answer';
  const heading = current.items.length > 1
    ? `${current.items.length} vouchers · ${template.title || 'Clarify this transaction'}`
    : (template.title || 'Clarify this transaction');

  const writeDraft = (patch: Partial<ClarificationAnswerDraft>) => {
    setDrafts((prev) => ({
      ...prev,
      [current.key]: {
        ...(prev[current.key] || initialClarificationDraft(current)),
        ...patch,
        answers: patch.answers || (prev[current.key] || initialClarificationDraft(current)).answers,
      },
    }));
  };

  const setAnswer = (metadataField: string, value: string) => {
    const base = drafts[current.key] || initialClarificationDraft(current);
    writeDraft({ answers: { ...base.answers, [metadataField]: value } });
    setErrors((prev) => {
      const next = { ...prev };
      delete next[metadataField];
      return next;
    });
  };

  const toggleSelected = (transactionId: string) => {
    const next = new Set(selectedIds);
    if (next.has(transactionId)) next.delete(transactionId);
    else next.add(transactionId);
    setSelectedByGroup((prev) => ({ ...prev, [current.key]: Array.from(next) }));
    setErrors((prev) => {
      const cleared = { ...prev };
      delete cleared.selection;
      return cleared;
    });
  };

  const submit = () => {
    const nextErrors = validateClarificationGroup(current, draft, selectedItems);
    if (Object.keys(nextErrors).length > 0) {
      setErrors(nextErrors);
      return;
    }
    setErrors({});
    onSubmitGroup(selectedItems.map((item) => ({
      item,
      body: buildClarificationAnswer(item, draft),
    })));
  };

  const renderField = (field: ClarificationField) => {
    const value = draft.answers[field.metadataField] || '';
    const error = errors[field.metadataField];
    if (field.kind === 'choice') {
      return (
        <FormControl key={field.id} fullWidth size="small" error={Boolean(error)} required={field.required}>
          <InputLabel id={`${field.id}-label`}>{field.label}</InputLabel>
          <Select
            labelId={`${field.id}-label`}
            label={field.label}
            value={value}
            onChange={(event) => setAnswer(field.metadataField, String(event.target.value))}
          >
            <MenuItem value="" disabled>Select</MenuItem>
            {(field.options || []).map((option) => (
              <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
            ))}
          </Select>
          {error ? <FormHelperText>{error}</FormHelperText> : null}
        </FormControl>
      );
    }
    return (
      <TextField
        key={field.id}
        size="small"
        label={field.label}
        type={field.kind === 'number' ? 'number' : 'text'}
        value={value}
        onChange={(event) => setAnswer(field.metadataField, event.target.value)}
        placeholder={field.kind === 'text' ? (template.example || '') : undefined}
        error={Boolean(error)}
        helperText={error || undefined}
        required={field.required}
        fullWidth
      />
    );
  };

  return (
    <Paper
      component="form"
      variant="outlined"
      aria-label="Clarification group"
      onSubmit={(event) => {
        event.preventDefault();
        submit();
      }}
      sx={{
        p: { xs: 1.5, sm: 2 },
        bgcolor: 'background.paper',
        borderColor: alpha(theme.palette.primary.main, 0.35),
      }}
    >
      <Stack spacing={2}>
        <Stack
          direction={{ xs: 'column', sm: 'row' }}
          spacing={1}
          sx={{ justifyContent: 'space-between', alignItems: { sm: 'flex-start' } }}
        >
          <Box sx={{ minWidth: 0 }}>
            <Typography variant="caption" color="text.secondary" aria-live="polite" display="block">
              {progress}
            </Typography>
            <Typography variant="caption" color="text.secondary" display="block">
              {`Clarification ${stepNumber} of ${stepTotal}`}
            </Typography>
            <Typography variant="h6" component="h2" sx={{ mt: 0.5, fontWeight: 700 }}>
              {heading}
            </Typography>
          </Box>
          <Chip size="small" color="warning" label="Not saved" sx={{ alignSelf: { xs: 'flex-start', sm: 'center' } }} />
        </Stack>

        {current.items.length === 1 ? <ContextFacts item={template} /> : null}
        {template.agentMessage ? (
          <Typography variant="body2">{template.agentMessage}</Typography>
        ) : null}
        {template.helper ? (
          <Alert severity="warning">{template.helper}</Alert>
        ) : null}
        {template.example ? (
          <Typography variant="body2" color="text.secondary">
            {`Example: ${template.example}`}
          </Typography>
        ) : null}

        {current.items.length > 1 ? (
          <FormGroup>
            <Typography variant="subtitle2" sx={{ mb: 0.5 }}>Vouchers in this group</Typography>
            <Stack direction="row" spacing={1} sx={{ mb: 0.5 }}>
              <Button
                type="button"
                size="small"
                onClick={() => setSelectedByGroup((prev) => ({
                  ...prev,
                  [current.key]: current.items.map((item) => item.transactionId),
                }))}
              >
                Select all vouchers
              </Button>
              <Button
                type="button"
                size="small"
                onClick={() => setSelectedByGroup((prev) => ({ ...prev, [current.key]: [] }))}
              >
                Clear selection
              </Button>
            </Stack>
            {current.items.map((item) => (
              <FormControlLabel
                key={item.transactionId}
                control={(
                  <Checkbox
                    size="small"
                    checked={selectedIds.has(item.transactionId)}
                    onChange={() => toggleSelected(item.transactionId)}
                  />
                )}
                label={voucherLabel(item)}
              />
            ))}
            {errors.selection ? <FormHelperText error>{errors.selection}</FormHelperText> : null}
            <Typography variant="caption" color="text.secondary">
              {`Saves ${selectedItems.length} selected voucher${selectedItems.length === 1 ? '' : 's'}.`}
            </Typography>
          </FormGroup>
        ) : null}

        <Stack spacing={1.5}>
          {fields.map(renderField)}
          {showFreeText(template) ? (
            <TextField
              size="small"
              label={template.question || 'What is this transaction?'}
              value={draft.text}
              onChange={(event) => {
                writeDraft({ text: event.target.value });
                setErrors((prev) => {
                  const next = { ...prev };
                  delete next.text;
                  return next;
                });
              }}
              placeholder={template.example || ''}
              error={Boolean(errors.text)}
              helperText={errors.text || undefined}
              fullWidth
              multiline
              minRows={2}
              required
            />
          ) : null}
          {template.requireMaterialName ? (
            <TextField
              size="small"
              label="Material or activity name"
              value={draft.materialName}
              onChange={(event) => {
                writeDraft({ materialName: event.target.value });
                setErrors((prev) => {
                  const next = { ...prev };
                  delete next.materialName;
                  return next;
                });
              }}
              error={Boolean(errors.materialName)}
              helperText={errors.materialName || undefined}
              fullWidth
            />
          ) : null}
          {template.requireAirports ? (
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <TextField
                size="small"
                label="Origin airport"
                value={draft.originAirport}
                onChange={(event) => writeDraft({ originAirport: event.target.value.toUpperCase() })}
                error={Boolean(errors.originAirport)}
                helperText={errors.originAirport || undefined}
                placeholder="BLR"
                fullWidth
              />
              <TextField
                size="small"
                label="Destination airport"
                value={draft.destinationAirport}
                onChange={(event) => writeDraft({ destinationAirport: event.target.value.toUpperCase() })}
                error={Boolean(errors.destinationAirport)}
                helperText={errors.destinationAirport || undefined}
                placeholder="DEL"
                fullWidth
              />
            </Stack>
          ) : null}
          {template.inputKind === 'unit_price' ? (
            <TextField
              size="small"
              label={template.unitPriceLabel || 'Unit price (₹)'}
              type="number"
              value={draft.answers.unitPriceInr || ''}
              onChange={(event) => setAnswer('unitPriceInr', event.target.value)}
              error={Boolean(errors.unitPriceInr)}
              helperText={errors.unitPriceInr || undefined}
              fullWidth
              required
            />
          ) : null}
          {template.inputKind !== 'unit_price' ? (template.extraFields || []).map((field) => (
            <TextField
              key={field.id}
              size="small"
              label={field.label}
              type="number"
              value={draft.answers[field.metadataField] || ''}
              onChange={(event) => setAnswer(field.metadataField, event.target.value)}
              fullWidth
            />
          )) : null}
          {template.inputKind !== 'unit_price' ? (
            <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
              <TextField
                size="small"
                label={template.quantityLabel || 'Quantity'}
                type="number"
                value={draft.quantity}
                onChange={(event) => {
                  writeDraft({ quantity: event.target.value, quantityEdited: true });
                  setErrors((prev) => {
                    const next = { ...prev };
                    delete next.quantity;
                    return next;
                  });
                }}
                error={Boolean(errors.quantity)}
                helperText={errors.quantity || (quantitiesDiffer(current)
                  ? 'Selected vouchers keep their own quantities unless you enter one here.'
                  : undefined)}
                placeholder={template.example || ''}
                fullWidth
              />
              {(template.unitOptions || []).length > 0 ? (
                <FormControl fullWidth size="small" error={Boolean(errors.unit)}>
                  <InputLabel id="clarification-unit-label">Unit</InputLabel>
                  <Select
                    labelId="clarification-unit-label"
                    label="Unit"
                    value={draft.unit}
                    onChange={(event) => {
                      writeDraft({ unit: String(event.target.value), unitEdited: true });
                      setErrors((prev) => {
                        const next = { ...prev };
                        delete next.unit;
                        return next;
                      });
                    }}
                  >
                    {(template.unitOptions || []).map((unit) => (
                      <MenuItem key={unit} value={unit}>{unit}</MenuItem>
                    ))}
                  </Select>
                  {errors.unit ? <FormHelperText>{errors.unit}</FormHelperText> : null}
                </FormControl>
              ) : (
                <TextField
                  size="small"
                  label="Unit"
                  value={draft.unit}
                  onChange={(event) => {
                    writeDraft({ unit: event.target.value, unitEdited: true });
                    setErrors((prev) => {
                      const next = { ...prev };
                      delete next.unit;
                      return next;
                    });
                  }}
                  placeholder={(template.unitOptions || []).join(', ')}
                  error={Boolean(errors.unit)}
                  helperText={errors.unit || undefined}
                  fullWidth
                />
              )}
            </Stack>
          ) : null}
        </Stack>

        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={1}>
          <Button type="button" variant="contained" color="primary" disabled={saving} onClick={submit}>
            {saving ? 'Saving…' : saveLabel}
          </Button>
          {groups.length > 1 ? (
            <Button
              type="button"
              variant="text"
              disabled={saving}
              onClick={() => {
                const index = groups.findIndex((group) => group.key === current.key);
                const next = groups[(index + 1) % groups.length];
                setErrors({});
                setActiveKey(next?.key || null);
              }}
            >
              Skip group
            </Button>
          ) : null}
        </Stack>
      </Stack>
    </Paper>
  );
};

export default ClarificationQueue;
