const SOURCE_FILTER_OPTIONS = [
  { value: 'all', label: 'All sources' },
  { value: 'connectors', label: 'Accounting connectors' },
  { value: 'documents', label: 'Uploaded bills/invoices' },
  { value: 'other', label: 'Other' },
] as const;

const formatSourceLabel = (transaction: OperationalTransaction) => {
  const extractedSource = transaction.metadata?.extractedData?.source;
  if (extractedSource === 'document_upload' || extractedSource === 'document_bulk_upload') {
    return 'Document upload';
  }
  if (CONNECTOR_SOURCES.has(transaction.source)) {
    return transaction.source.charAt(0).toUpperCase() + transaction.source.slice(1);
  }
  if (transaction.source === 'manual' && extractedSource) {
    return String(extractedSource).replace(/_/g, ' ');
  }
  return transaction.source;
};

const resolveBoundary = (transaction: OperationalTransaction): 'company' | 'product' => {
  const boundary =
    transaction.emissionBoundary ||
    transaction.metadata?.extractedData?.emissionBoundary ||
    transaction.metadata?.extractedData?.transactionMapping ||
    transaction.emissionClassification?.level;
  return boundary === 'product' ? 'product' : 'company';
};

const isDocumentTransaction = (transaction: OperationalTransaction) => {
  const extractedSource = transaction.metadata?.extractedData?.source;
  return (
    extractedSource === 'document_upload' ||
    extractedSource === 'document_bulk_upload' ||
    extractedSource === 'document_batch_ai_model'
  );
};

const isConnectorTransaction = (transaction: OperationalTransaction) =>
  CONNECTOR_SOURCES.has(transaction.source);

const matchesSourceFilter = (
  transaction: OperationalTransaction,
  filter: (typeof SOURCE_FILTER_OPTIONS)[number]['value']
) => {
  if (filter === 'all') return true;
  if (filter === 'connectors') return isConnectorTransaction(transaction);
  if (filter === 'documents') return isDocumentTransaction(transaction);
  return !isConnectorTransaction(transaction) && !isDocumentTransaction(transaction);
};

const isUnclassifiedTransaction = (transaction: OperationalTransaction) =>
  !transaction.emissionClassification?.level;

const isExceptionTransaction = (transaction: OperationalTransaction) => {
  const confidence = transaction.productAttribution?.assignmentConfidence;
  return (
    isUnclassifiedTransaction(transaction)
    || (typeof confidence === 'number' && confidence < 0.7)
  );
};

const isProvisionalInventoryTransaction = (transaction: OperationalTransaction) => {
  const status = String(transaction.metadata?.inventoryStatus || '').toLowerCase();
  if (status === 'provisional') {
    return true;
  }
  return transaction.metadata?.pendingUserVerification === true;
};

const matchesDateRange = (transaction: OperationalTransaction, from: string, to: string) => {
  const txnTime = new Date(transaction.date).getTime();
  if (Number.isNaN(txnTime)) return true;
  if (from) {
    const fromTime = new Date(from).getTime();
    if (!Number.isNaN(fromTime) && txnTime < fromTime) return false;
  }
  if (to) {
    const toTime = new Date(to).getTime();
    if (!Number.isNaN(toTime) && txnTime > toTime + 86_400_000 - 1) return false;
  }
  return true;
};

