const ActivityEmissionValue: React.FC<{
  txn: OperationalTransaction;
  calculationTone: 'activity' | 'spend_proxy' | 'estimate' | null;
  toneLabel?: string;
}> = ({ txn, calculationTone, toneLabel }) => {
  const inventoryKg = Number(txn.carbonFootprint?.co2Emissions || 0);
  const screeningKg = Number(txn.carbonFootprint?.screeningCo2Emissions || 0);
  const useScreening = calculationTone !== 'activity' && inventoryKg <= 0 && screeningKg > 0;
  const formula = buildTransactionCalculationReadout(txn.carbonFootprint, {
    amount: txn.amount,
    category: txn.category,
    subcategory: txn.subcategory,
    quantity: txn.quantity,
    unit: txn.unit,
    description: txn.description,
  }).inlineFormula;
  const complianceFlags = txn.carbonFootprint?.complianceFlags;
  const electricityQuantityMismatch = Array.isArray(complianceFlags)
    && complianceFlags.includes('electricity_quantity_amount_mismatch');
  const needsElectricityBill = !electricityQuantityMismatch
    && Array.isArray(complianceFlags)
    && complianceFlags.includes('electricity_requires_bill_quantity');
  return (
    <>
      <Typography variant="body2" sx={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
        {(useScreening ? screeningKg : inventoryKg).toFixed(2)}
      </Typography>
      {electricityQuantityMismatch ? (
        <Typography variant="caption" color="error.main" display="block" sx={{ whiteSpace: 'normal', overflowWrap: 'anywhere', textAlign: 'left' }}>
          Quantity does not match the amount. Upload the electricity bill for verification before carbon is calculated.
        </Typography>
      ) : null}
      {needsElectricityBill ? (
        <Typography variant="caption" color="warning.main" display="block" sx={{ whiteSpace: 'normal', overflowWrap: 'anywhere', textAlign: 'left' }}>
          Upload the electricity bill and enter the quantity and unit (kWh).
        </Typography>
      ) : null}
      {formula ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ whiteSpace: 'normal', overflowWrap: 'anywhere', textAlign: 'left' }}>
          {formula}
        </Typography>
      ) : null}
      {useScreening && toneLabel ? (
        <Typography variant="caption" color="text.secondary" display="block" sx={{ textAlign: 'left' }}>
          {toneLabel}
        </Typography>
      ) : null}
    </>
  );
};

