const OperationalTransactionsTable: React.FC<OperationalTransactionsTableProps> = ({
  refreshToken = 0,
  title = 'Operational data',
  description = 'Transactions from linked accounting connectors and uploaded bills/invoices. Classify each row or multiple rows as company-level or manufactured product-level to split carbon emissions correctly.',
  ownershipReviewOnly: ownershipReviewOnlyProp = false,
}) => {
  const theme = useTheme();
  const worksheetFullScreen = useMediaQuery(theme.breakpoints.down('sm'));
  const paneObserverRef = useRef<ResizeObserver | null>(null);
  const [tablePaneWidth, setTablePaneWidth] = useState(guessActivityPaneWidth);
  const stackedActivityRows = tablePaneWidth < STACKED_ACTIVITY_PANE_PX;
  const setTablePaneNode = useCallback((node: HTMLDivElement | null) => {
    paneObserverRef.current?.disconnect();
    paneObserverRef.current = null;
    if (!node || typeof ResizeObserver === 'undefined') return;
    const publish = (width: number) => {
      const next = Math.round(width);
      if (next <= 0) return;
      setTablePaneWidth((current) => (current === next ? current : next));
    };
    publish(node.clientWidth);
    const observer = new ResizeObserver((entries) => {
      publish(entries[0]?.contentRect.width ?? node.clientWidth);
    });
    observer.observe(node);
    paneObserverRef.current = observer;
  }, []);
  useEffect(() => () => paneObserverRef.current?.disconnect(), []);
  const [transactions, setTransactions] = useState<OperationalTransaction[]>([]);
  const [productCatalog, setProductCatalog] = useState<ProductCatalogEntry[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [success, setSuccess] = useState<string | null>(null);
  const [sourceFilter, setSourceFilter] = useState<(typeof SOURCE_FILTER_OPTIONS)[number]['value']>('all');
  const [unclassifiedOnly, setUnclassifiedOnly] = useState(false);
  const [exceptionsOnly, setExceptionsOnly] = useState(false);
  const [provisionalOnly, setProvisionalOnly] = useState(false);
  const [estimateRationaleOpen, setEstimateRationaleOpen] = useState(false);
  const [discrepanciesOpen, setDiscrepanciesOpen] = useState(false);
  const [ownershipReviewOnly, setOwnershipReviewOnly] = useState(ownershipReviewOnlyProp);
  const [autoClassifying, setAutoClassifying] = useState(false);
  const [agentOpen, setAgentOpen] = useState(false);
  const [agentLoading, setAgentLoading] = useState(false);
  const [agentSaving, setAgentSaving] = useState(false);
  const [agentError, setAgentError] = useState<string | null>(null);
  const [agentQuestions, setAgentQuestions] = useState<UncertaintyClarificationQuestion[]>([]);
  const [agentIdentified, setAgentIdentified] = useState<IdentifiedSpendPrice[]>([]);
  const [dateFrom, setDateFrom] = useState('');
  const [dateTo, setDateTo] = useState('');
  const [searchInput, setSearchInput] = useState('');
  const [searchQuery, setSearchQuery] = useState('');
  const [page, setPage] = useState(0);
  const [rowsPerPage, setRowsPerPage] = useState(DEFAULT_ROWS_PER_PAGE);
  const [paginationTotal, setPaginationTotal] = useState(0);
  const [selectedIds, setSelectedIds] = useState<Set<string>>(new Set());
  const [detailTxn, setDetailTxn] = useState<OperationalTransaction | null>(null);
  const [detailOwnership, setDetailOwnership] = useState('');
  const [savingOwnership, setSavingOwnership] = useState(false);
  const worksheetOwnershipEditable = ['transportation', 'energy'].includes(
    String(detailTxn?.category || '').toLowerCase()
  );
  const [inputTxn, setInputTxn] = useState<OperationalTransaction | null>(null);
  const [inputBasis, setInputBasis] = useState<'activity' | 'spend'>('activity');
  const [inputQuantity, setInputQuantity] = useState('');
  const [inputUnit, setInputUnit] = useState('');
  const [inputPrice, setInputPrice] = useState('');
  const [inputMaterial, setInputMaterial] = useState('');
  const [scopeTxn, setScopeTxn] = useState<OperationalTransaction | null>(null);
  const [scopeAnswers, setScopeAnswers] = useState<Record<string, string>>({});
  const [savingScope, setSavingScope] = useState(false);
  const [inputOrigin, setInputOrigin] = useState('');
  const [inputDestination, setInputDestination] = useState('');
  const [inputExtras, setInputExtras] = useState<Record<string, string>>({});
  const [inputStep, setInputStep] = useState<'bill' | 'clarify' | 'fields'>('fields');
  const [inputClarification, setInputClarification] = useState('');
  const [inputBill, setInputBill] = useState<File | null>(null);
  const [evidenceDocumentId, setEvidenceDocumentId] = useState('');
  const [billChecks, setBillChecks] = useState<Array<{ field: string; status: string; message: string }>>([]);
  const [readingBill, setReadingBill] = useState(false);
  const [savingInput, setSavingInput] = useState(false);
  const [classifyDialogOpen, setClassifyDialogOpen] = useState(false);
  const [classifyTargetIds, setClassifyTargetIds] = useState<string[]>([]);
  const [classifyBoundary, setClassifyBoundary] = useState<'company' | 'product'>('company');
  const [classifyProducts, setClassifyProducts] = useState<string[]>([]);
  const [classifyReason, setClassifyReason] = useState('');
  const [classifying, setClassifying] = useState(false);
  const fetchRequestIdRef = useRef(0);
  const pageRef = useRef(0);
  const rowsPerPageRef = useRef(DEFAULT_ROWS_PER_PAGE);
  const searchRef = useRef('');
  const searchInitializedRef = useRef(false);
  const lastFetchedSearchRef = useRef<string | null>(null);
  pageRef.current = page;
  rowsPerPageRef.current = rowsPerPage;
  searchRef.current = searchQuery;

  const fetchTransactions = useCallback(async (
    uiPage: number,
    limit: number,
    options: { includeCatalog?: boolean } = {}
  ) => {
    const requestId = fetchRequestIdRef.current + 1;
    fetchRequestIdRef.current = requestId;
    lastFetchedSearchRef.current = searchRef.current;
    setLoading(true);
    setError(null);
    try {
      const [txnResponse, catalogResponse] = await Promise.all([
        ApiService.getTransactions({
          page: uiPage + 1,
          limit,
          sortBy: 'createdAt',
          sortOrder: 'desc',
          search: searchRef.current || undefined,
        }),
        options.includeCatalog
          ? ApiService.getTransactionProductCatalog().catch(() => null)
          : Promise.resolve(undefined),
      ]);

      if (requestId !== fetchRequestIdRef.current) {
        return false;
      }

      const rows = Array.isArray(txnResponse?.data?.transactions)
        ? (txnResponse.data.transactions as OperationalTransaction[])
        : [];
      const reportedTotal = Number(txnResponse?.data?.pagination?.total);

      setTransactions(rows);
      if (Number.isFinite(reportedTotal) && reportedTotal >= 0) {
        setPaginationTotal(reportedTotal);
      }
      setPage(uiPage);
      setRowsPerPage(limit);

      if (options.includeCatalog && catalogResponse !== undefined) {
        const catalogProducts = catalogResponse?.data?.products;
        setProductCatalog(Array.isArray(catalogProducts) ? catalogProducts : []);
      }
      return true;
    } catch (err: unknown) {
      if (requestId !== fetchRequestIdRef.current) {
        return false;
      }
      console.error('Error loading operational transactions:', err);
      setError(err instanceof Error ? err.message : 'Unable to load operational data');
      return false;
    } finally {
      if (requestId === fetchRequestIdRef.current) {
        setLoading(false);
      }
    }
  }, []);

  const loadData = useCallback(async () => {
    await fetchTransactions(pageRef.current, rowsPerPageRef.current, { includeCatalog: true });
  }, [fetchTransactions]);

  useEffect(() => {
    void fetchTransactions(pageRef.current, rowsPerPageRef.current, { includeCatalog: true });
  }, [fetchTransactions, refreshToken]);

  useEffect(() => {
    const handle = window.setTimeout(() => {
      setSearchQuery(searchInput.trim());
    }, 300);
    return () => window.clearTimeout(handle);
  }, [searchInput]);

  useEffect(() => {
    if (!searchInitializedRef.current) {
      searchInitializedRef.current = true;
      return;
    }
    if (searchQuery === lastFetchedSearchRef.current) {
      return;
    }
    void fetchTransactions(0, rowsPerPageRef.current);
  }, [searchQuery, fetchTransactions]);

  useEffect(() => {
    setOwnershipReviewOnly(ownershipReviewOnlyProp);
    if (ownershipReviewOnlyProp) {
      setPage(0);
    }
  }, [ownershipReviewOnlyProp]);

  const filteredTransactions = useMemo(
    () =>
      transactions.filter((txn) => {
        if (!matchesSourceFilter(txn, sourceFilter)) return false;
        if (unclassifiedOnly && !isUnclassifiedTransaction(txn)) return false;
        if (exceptionsOnly && !isExceptionTransaction(txn)) return false;
        if (provisionalOnly && !isProvisionalInventoryTransaction(txn)) return false;
        if (ownershipReviewOnly && !needsOwnershipReview(txn)) return false;
        if (!matchesDateRange(txn, dateFrom, dateTo)) return false;
        return true;
      }),
    [transactions, sourceFilter, unclassifiedOnly, exceptionsOnly, provisionalOnly, ownershipReviewOnly, dateFrom, dateTo]
  );

  const estimateScreening = useMemo(
    () => summarizeEstimateScreening(filteredTransactions),
    [filteredTransactions]
  );

  const discrepancyRows = useMemo(() => (
    filteredTransactions
      .flatMap((txn) => collectCalculationDiscrepancies(txn).map((entry) => ({ txn, entry })))
      .sort((left, right) => (
        (left.entry.severity || 0) - (right.entry.severity || 0)
        || (left.entry.order || 0) - (right.entry.order || 0)
      ))
  ), [filteredTransactions]);

  const openDiscrepancy = (txn: OperationalTransaction, field?: string | null) => {
    const scopeField = field === 'fuel_combustion_control'
      || field === 'transport_control'
      || field === 'purchase_class'
      || field === 'activity_unit'
      || field === 'fuel_type';
    if (scopeField && txn.scopeClassification?.status === 'needs_input') {
      setScopeTxn(txn);
      setScopeAnswers({});
      return;
    }
    openMissingDataDialog(txn);
  };

  const inputPrompt = inputTxn ? resolveMissingCarbonInput(inputTxn) : null;

  const openMissingDataDialog = (txn?: OperationalTransaction) => {
    const target = txn || filteredTransactions.find((row) => isEstimateOrMiscellaneousTransaction(row).match);
    if (!target) return;
    const prompt = resolveMissingCarbonInput(target);
    setInputTxn(target);
    setInputStep(prompt?.clarificationDirect
      ? 'clarify'
      : prompt?.descriptionUncertain
        ? (isBillUploadEnabled() ? 'bill' : 'clarify')
        : 'fields');
    setInputClarification('');
    setInputBasis(prompt?.activity ? 'activity' : 'spend');
    setInputQuantity(target.quantity ? String(target.quantity) : '');
    setInputUnit(prompt?.activity?.unit || target.unit || '');
    setInputPrice('');
    setInputMaterial('');
    setInputOrigin('');
    setInputDestination('');
    setInputExtras({});
    setInputBill(null);
    setEvidenceDocumentId('');
    setBillChecks([]);
    setReadingBill(false);
  };

  const readBillAgainstMissingInputs = async (file: File) => {
    if (!inputTxn?._id) return;
    setInputBill(file);
    setReadingBill(true);
    setBillChecks([]);
    setError(null);
    try {
      const uploaded = await documentService.uploadDocument(
        file,
        'bill',
        `Activity evidence for ${inputTxn.description || inputTxn._id}`,
        'company',
        [],
        {
          sourceWorkflow: 'activity_basis_evidence',
          linkedTransactionId: inputTxn._id,
          linkedSourceId: inputTxn.sourceId
        }
      );
      const documentId = uploaded?.document?.id;
      if (!documentId) {
        throw new Error('The bill upload did not return a document id.');
      }
      setEvidenceDocumentId(documentId);
      type BillCrossCheckResult = {
        status?: string;
        checks?: Array<{ field: string; status: string; message: string }>;
        suggested?: {
          quantity?: number | null;
          unit?: string | null;
          materialName?: string | null;
          originAirport?: string;
          destinationAirport?: string;
          extras?: Record<string, number | null> | null;
        };
        canAutoApply?: boolean;
        applied?: boolean;
      };
      let latest: BillCrossCheckResult | null = null;
      for (let attempt = 0; attempt < 4; attempt += 1) {
        const response = await ApiService.crossCheckTransactionBill(inputTxn._id, documentId) as {
          data?: BillCrossCheckResult;
        };
        latest = response?.data || null;
        if (latest?.status === 'pending' && attempt < 3) {
          await new Promise((resolve) => setTimeout(resolve, 1500));
          continue;
        }
        break;
      }
      setBillChecks(latest?.checks || []);
      if (latest?.suggested?.quantity) setInputQuantity(String(latest.suggested.quantity));
      if (latest?.suggested?.unit) setInputUnit(latest.suggested.unit);
      if (latest?.suggested?.materialName) setInputMaterial(latest.suggested.materialName);
      if (latest?.suggested?.extras) {
        setInputExtras((current) => {
          const next = { ...current };
          Object.entries(latest?.suggested?.extras || {}).forEach(([key, value]) => {
            if (value != null && Number(value) > 0) next[key] = String(value);
          });
          return next;
        });
      }
      if (latest?.suggested?.originAirport) setInputOrigin(latest.suggested.originAirport);
      if (latest?.suggested?.destinationAirport) setInputDestination(latest.suggested.destinationAirport);
      if (!latest?.applied && inputPrompt?.descriptionUncertain) setInputStep('clarify');
      if (latest?.applied) {
        await loadData();
        setInputTxn(null);
        setSuccess('The bill matches the missing activity. The footprint was recalculated as activity-based.');
      }
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to read the bill');
    } finally {
      setReadingBill(false);
    }
  };

  const saveMissingCarbonInput = async () => {
    if (!inputTxn?._id) return;
    const clarifyingWithoutBill = inputStep === 'clarify' && !inputBill && !evidenceDocumentId;
    const promptFields = Array.isArray(inputPrompt?.activity?.fields) ? inputPrompt.activity.fields : [];
    const missingField = inputBasis === 'activity'
      ? promptFields.find((field: { metadataField: string; label: string; kind?: string; required?: boolean }) => {
        const value = String(inputExtras[field.metadataField] || '').trim();
        if (!field.required) return false;
        return field.kind === 'number' ? !(Number(value) > 0) : !value;
      })
      : undefined;
    if (missingField) {
      setError(`Enter ${missingField.label}.`);
      return;
    }
    if (inputBasis === 'activity' && inputExtras.fertilizerType === 'other' && !String(inputExtras.fertilizerProductName || inputMaterial || '').trim()) {
      setError('Name the fertilizer product when the type is Other.');
      return;
    }
    const structuredNote = promptFields.flatMap((field: { metadataField: string; label: string; kind?: string; options?: Array<{ value: string; label: string }> }) => {
      const value = String(inputExtras[field.metadataField] || '').trim();
      if (!value) return [];
      if (field.kind === 'choice') {
        return [field.options?.find((option) => option.value === value)?.label || value];
      }
      if (field.kind === 'number') return [`${value} ${field.label}`];
      return [value];
    }).join(', ');
    const promptId = String(inputPrompt?.id || '');
    const quantityNote = (promptId === 'activity_quantity_missing' || promptId === 'service_count_missing')
      && Number(inputQuantity) > 0
      && inputUnit.trim()
      ? `${Number(inputQuantity)} ${inputUnit.trim()}`
      : '';
    const clarificationNote = inputClarification.trim().length >= 3
      ? inputClarification.trim()
      : (structuredNote || quantityNote);
    if (clarifyingWithoutBill && clarificationNote.length < 3) {
      setError('Describe what this transaction is. The voucher description does not say.');
      return;
    }
    if (isBillUploadEnabled() && inputBasis === 'activity' && !inputBill && !evidenceDocumentId && !clarifyingWithoutBill) {
      setError('Upload the bill as evidence for an activity-based calculation.');
      return;
    }
    setSavingInput(true);
    setError(null);
    try {
      let savedEvidenceId = evidenceDocumentId;
      if (inputBasis === 'activity' && inputBill && !savedEvidenceId) {
        const uploaded = await documentService.uploadDocument(
          inputBill,
          'bill',
          `Activity evidence for ${inputTxn.description || inputTxn._id}`,
          'company',
          [],
          {
            sourceWorkflow: 'activity_basis_evidence',
            linkedTransactionId: inputTxn._id,
            linkedSourceId: inputTxn.sourceId
          }
        );
        savedEvidenceId = uploaded?.document?.id || '';
        if (!savedEvidenceId) {
          throw new Error('The bill upload did not return a document id.');
        }
      }
      await ApiService.updateTransaction(inputTxn._id, {
        carbonInputBasis: inputBasis,
        quantity: inputBasis === 'activity' ? Number(inputQuantity) : undefined,
        unit: inputBasis === 'activity' ? inputUnit : undefined,
        unitPriceInr: inputBasis === 'spend' ? Number(inputPrice) : undefined,
        materialName: inputMaterial || undefined,
        originAirport: inputOrigin || undefined,
        destinationAirport: inputDestination || undefined,
        evidenceDocumentId: inputBasis === 'activity' ? savedEvidenceId : undefined,
        transactionClarification: clarificationNote || undefined,
        clarificationWithoutBill: clarifyingWithoutBill || undefined,
        ...Object.fromEntries(
          Object.entries(inputExtras).filter(([, value]) => {
            const text = String(value || '').trim();
            return text.length > 0 && (Number(text) > 0 || Number.isNaN(Number(text)) || /[a-z]/i.test(text));
          })
        )
      });
      await loadData();
      setInputTxn(null);
        setSuccess(inputBasis === 'activity'
        ? (clarifyingWithoutBill
          ? 'The transaction clarification was saved. Carbon footprint recalculated from the activity you entered.'
          : 'Activity data saved with the bill as evidence. Carbon footprint recalculated as activity-based.')
        : 'Spend data saved. Carbon footprint recalculated as spend-based.');
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Failed to save carbon inputs');
    } finally {
      setSavingInput(false);
    }
  };

  const provisionalInventoryCount = useMemo(
    () => transactions.filter((txn) => isProvisionalInventoryTransaction(txn)).length,
    [transactions]
  );

  const transportDoubleCountMonths = useMemo(
    () => findTransportDoubleCountMonths(transactions),
    [transactions]
  );

  const ownershipReviewCount = useMemo(
    () => countOwnershipReviewCandidates(transactions),
    [transactions]
  );

  const classifyPreviewSummary = useMemo(() => {
    const targets = transactions.filter((txn) => classifyTargetIds.includes(txn._id));
    const companyCount = targets.filter((txn) => resolveBoundary(txn) === 'company').length;
    const productCount = targets.length - companyCount;
    return { targets, companyCount, productCount };
  }, [transactions, classifyTargetIds]);

  const localFiltersActive = Boolean(
    sourceFilter !== 'all'
    || unclassifiedOnly
    || exceptionsOnly
    || provisionalOnly
    || ownershipReviewOnly
    || dateFrom
    || dateTo
  );

  const allVisibleSelected =
    filteredTransactions.length > 0 &&
    filteredTransactions.every((txn) => selectedIds.has(txn._id));

  const someVisibleSelected = filteredTransactions.some((txn) => selectedIds.has(txn._id));

  const openClassifyDialog = (ids: string[]) => {
    if (ids.length === 0) return;
    const first = transactions.find((txn) => txn._id === ids[0]);
    const boundary = first ? resolveBoundary(first) : 'company';
    const assignedProducts = (first?.productAttribution?.assignedProducts || [])
      .map((entry) => entry.productName)
      .filter(Boolean) as string[];

    setClassifyTargetIds(ids);
    setClassifyBoundary(boundary);
    setClassifyProducts(assignedProducts);
    setClassifyReason('');
    setClassifyDialogOpen(true);
  };

  const handleToggleSelectAll = () => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (allVisibleSelected) {
        filteredTransactions.forEach((txn) => next.delete(txn._id));
      } else {
        filteredTransactions.forEach((txn) => next.add(txn._id));
      }
      return next;
    });
  };

  const handleToggleRow = (id: string) => {
    setSelectedIds((prev) => {
      const next = new Set(prev);
      if (next.has(id)) {
        next.delete(id);
      } else {
        next.add(id);
      }
      return next;
    });
  };

  const openUncertaintyAgent = async () => {
    setAgentOpen(true);
    setAgentLoading(true);
    setAgentError(null);
    try {
      const response = await ApiService.getUncertaintyClarifications() as {
        success?: boolean;
        message?: string;
        data?: { questions?: UncertaintyClarificationQuestion[]; identifiedPrices?: IdentifiedSpendPrice[] };
      };
      applyUncertaintyReview(response);
      if ((response?.data?.identifiedPrices || []).length > 0) await loadData();
    } catch (err: unknown) {
      setAgentQuestions([]);
      setAgentError(err instanceof Error ? err.message : 'The carbon clarification agent could not review these transactions.');
    } finally {
      setAgentLoading(false);
    }
  };

  const applyUncertaintyReview = (response: {
    success?: boolean;
    message?: string;
    data?: { questions?: UncertaintyClarificationQuestion[]; identifiedPrices?: IdentifiedSpendPrice[] };
  }) => {
    if (response?.success === false) {
      throw new Error(response?.message || 'The carbon clarification agent could not review these transactions.');
    }
    const identifiedPrices = response?.data?.identifiedPrices;
    const questions = response?.data?.questions;
    setAgentQuestions(Array.isArray(questions) ? questions : []);
    setAgentIdentified(Array.isArray(identifiedPrices) ? identifiedPrices : []);
  };

  const saveUncertaintyGroup = async (entries: UncertaintyAnswerEntry[]) => {
    if (entries.length === 0) return;
    setAgentSaving(true);
    setAgentError(null);
    const saved: string[] = [];
    try {
      for (const entry of entries) {
        const response = await ApiService.updateTransaction(entry.question.transactionId, entry.body);
        if (response?.success === false) {
          throw new Error(response?.message || 'The answer was not saved.');
        }
        saved.push(entry.question.transactionId);
      }
      setSuccess(saved.length === 1
        ? 'The agent saved that answer and recalculated the row.'
        : `The agent saved ${saved.length} answers and recalculated those rows.`);
    } catch (err: unknown) {
      setAgentError(err instanceof Error ? err.message : 'The answer was not saved.');
    } finally {
      if (saved.length > 0) {
        setAgentQuestions((current) => current.filter((item) => !saved.includes(item.transactionId)));
        await loadData();
      }
      setAgentSaving(false);
    }
  };

  const undoIdentifiedPrice = async (row: IdentifiedSpendPrice) => {
    setAgentSaving(true);
    setAgentError(null);
    try {
      const response = await ApiService.updateTransaction(row.transactionId, { revertCitedUnitPrice: true });
      if (response?.success === false) {
        throw new Error(response?.message || 'The cited unit price was not removed.');
      }
      const review = await ApiService.getUncertaintyClarifications() as {
        success?: boolean;
        message?: string;
        data?: { questions?: UncertaintyClarificationQuestion[]; identifiedPrices?: IdentifiedSpendPrice[] };
      };
      applyUncertaintyReview(review);
      setSuccess('The cited unit price was removed. That voucher is back in the clarification queue if it still needs an answer.');
      await loadData();
    } catch (err: unknown) {
      setAgentError(err instanceof Error ? err.message : 'The cited unit price was not removed.');
    } finally {
      setAgentSaving(false);
    }
  };

  const handleAutoClassifyWithAi = async () => {
    setAutoClassifying(true);
    setError(null);
    try {
      const response = await ApiService.orchestrateProductPcf({
        transactionIds: selectedIds.size > 0 ? Array.from(selectedIds) : undefined,
        includeUnifiedView: false,
      });
      if ((response as { success?: boolean })?.success === false) {
        throw new Error((response as { message?: string })?.message || 'AI classification failed');
      }
      const data = (response as { data?: { classification?: { processed?: number; exceptions?: unknown[] } } })?.data;
      const classification = (data?.classification ?? data) as { processed?: number; exceptions?: unknown[] } | undefined;
      const exceptions = classification?.exceptions;
      const excCount = Array.isArray(exceptions) ? exceptions.length : 0;
      setSuccess(
        `AI auto-classified ${classification?.processed ?? 0} transactions. ${excCount} need manual review.`
      );
      setSelectedIds(new Set());
      await loadData();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'AI classification failed');
    } finally {
      setAutoClassifying(false);
    }
  };

  const handleApplyClassification = async () => {
    if (classifyTargetIds.length === 0) return;
    if (classifyBoundary === 'product' && classifyProducts.length === 0) {
      setError('Select at least one manufactured product from your profile.');
      return;
    }

    setClassifying(true);
    setError(null);
    try {
      const response = await ApiService.classifyTransactions({
        transactionIds: classifyTargetIds,
        emissionBoundary: classifyBoundary,
        productNames: classifyBoundary === 'product' ? classifyProducts : [],
        reason: classifyReason.trim() || undefined,
      });

      if (response?.success === false) {
        throw new Error(response?.message || 'Classification failed');
      }

      setSuccess(response?.message || 'Transactions classified successfully');
      setClassifyDialogOpen(false);
      setSelectedIds(new Set());
      await loadData();
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Classification failed');
    } finally {
      setClassifying(false);
    }
  };

  const handleExportAuditWorkbook = async () => {
    setError(null);
    try {
      const { blob, fileName } = await ApiService.downloadTransactionAuditWorkbook({
        startDate: dateFrom || undefined,
        endDate: dateTo || undefined,
        source: sourceFilter,
      });
      const url = URL.createObjectURL(blob);
      const link = document.createElement('a');
      link.href = url;
      link.download = fileName;
      link.click();
      URL.revokeObjectURL(url);
      setSuccess('Downloaded the transaction audit workbook.');
    } catch (err: unknown) {
      setError(err instanceof Error ? err.message : 'Unable to download the audit workbook');
    }
  };

  const handleExportCsv = () => {
    const rows = buildOperationalExportRows(filteredTransactions, {
      includeDescription: !HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI,
      formatSourceLabel,
      resolveBoundary,
    });
    const csv = operationalRowsToCsv(rows, filteredTransactions);
    if (!csv) {
      setError('No rows to export for the current filters.');
      return;
    }
    downloadOperationalCsv(csv);
    const review = summarizeConsultantReview(filteredTransactions);
    setSuccess(
      `Exported ${rows.length} transaction${rows.length === 1 ? '' : 's'}. `
      + `Without calculation: ${review.counts.withoutCalculation}. `
      + `Spend-based: ${review.counts.spendBased}.`,
    );
  };

  const hasOperationalData = paginationTotal > 0 || transactions.length > 0;

  const estimateRationaleDetails = (
    <Box sx={{ mt: 0.5 }}>
      <Button
        size="small"
        color="inherit"
        variant="outlined"
        aria-expanded={estimateRationaleOpen}
        aria-controls="estimate-rationale-details"
        onClick={() => setEstimateRationaleOpen((open) => !open)}
        sx={{ height: 32, minHeight: 32, px: 1.25, py: 0 }}
      >
        Why am I seeing this?
      </Button>
      <Typography
        id="estimate-rationale-details"
        variant="caption"
        component="p"
        hidden={!estimateRationaleOpen}
        sx={{ mt: 0.75, mb: 0 }}
      >
        {ESTIMATE_RATIONALE}
      </Typography>
    </Box>
  );

  return (
    <Paper id="operational-data" variant="outlined" sx={{ p: 2, mt: 3 }}>
      <Box sx={{ mb: 2 }}>
        <Box>
          <Typography variant="h6" component="h2" gutterBottom>
            {title}
          </Typography>
          <Typography variant="body2" color="text.secondary">
            {description}
          </Typography>
          <Box sx={{ mt: 1 }}>
            <ComplianceMethodologyBadge compact />
          </Box>
        </Box>

        <Box
          sx={{
            mt: 1.5,
            display: 'flex',
            flexDirection: 'column',
            gap: 1,
            p: { xs: 1.25, sm: 1.5 },
            borderRadius: 2,
            border: '1px solid',
            borderColor: (theme) =>
              theme.palette.mode === 'dark' ? 'rgba(148, 163, 184, 0.22)' : 'rgba(148, 163, 184, 0.28)',
            bgcolor: (theme) =>
              theme.palette.mode === 'dark' ? 'rgba(255, 255, 255, 0.03)' : 'rgba(15, 23, 42, 0.03)',
          }}
        >
          <Box
            role="group"
            aria-label="Filters"
            sx={{
              display: 'grid',
              gap: 1,
              minWidth: 0,
              alignItems: 'center',
              gridTemplateColumns: {
                xs: 'minmax(0, 1fr)',
                sm: 'minmax(0, 1fr) minmax(148px, 220px)',
              },
            }}
          >
            <TextField
              size="small"
              label="Search by date or amount"
              placeholder="2024-03-01 or 12000"
              value={searchInput}
              onChange={(event) => setSearchInput(event.target.value)}
              inputProps={{ 'aria-label': 'Search transactions by date or amount' }}
              sx={toolbarControlSx}
            />
            <FormControl size="small" sx={toolbarControlSx}>
              <InputLabel id="operational-source-filter-label">Source</InputLabel>
              <Select
                labelId="operational-source-filter-label"
                label="Source"
                value={sourceFilter}
                onChange={(event) => {
                  setSourceFilter(event.target.value as typeof sourceFilter);
                  setPage(0);
                }}
              >
                {SOURCE_FILTER_OPTIONS.map((option) => (
                  <MenuItem key={option.value} value={option.value}>
                    {option.label}
                  </MenuItem>
                ))}
              </Select>
            </FormControl>
          </Box>

          <Box
            role="group"
            aria-label="Date range and classification"
            sx={{
              display: 'grid',
              gap: 1,
              minWidth: 0,
              alignItems: 'center',
              gridTemplateColumns: {
                xs: 'minmax(0, 1fr) minmax(0, 1fr)',
                md: 'minmax(0, 1fr) minmax(0, 1fr) auto',
              },
            }}
          >
            <TextField
              size="small"
              type="date"
              label="From"
              value={dateFrom}
              onChange={(event) => {
                setDateFrom(event.target.value);
                setPage(0);
              }}
              InputLabelProps={{ shrink: true }}
              inputProps={{ min: '1990-01-01', max: `${new Date().getUTCFullYear() + 1}-12-31` }}
              sx={toolbarDateFieldSx}
            />
            <TextField
              size="small"
              type="date"
              label="To"
              value={dateTo}
              onChange={(event) => {
                setDateTo(event.target.value);
                setPage(0);
              }}
              InputLabelProps={{ shrink: true }}
              inputProps={{ min: '1990-01-01', max: `${new Date().getUTCFullYear() + 1}-12-31` }}
              sx={toolbarDateFieldSx}
            />
            <Button
              size="small"
              variant="outlined"
              color="secondary"
              startIcon={<AiIcon />}
              onClick={() => void openUncertaintyAgent()}
              disabled={loading || agentLoading}
              sx={{
                ...toolbarActionButtonSx,
                gridColumn: { xs: '1 / -1', md: 'auto' },
                width: { xs: '100%', md: 'auto' },
              }}
            >
              {agentLoading ? 'Reviewing…' : 'Ask carbon agent'}
            </Button>
            <Button
              size="small"
              variant="outlined"
              color="primary"
              startIcon={<AiIcon />}
              onClick={() => void handleAutoClassifyWithAi()}
              disabled={loading || autoClassifying}
              sx={{
                ...toolbarActionButtonSx,
                gridColumn: { xs: '1 / -1', md: 'auto' },
                width: { xs: '100%', md: 'auto' },
              }}
            >
              {autoClassifying ? 'Running AI…' : 'Auto-classify with AI'}
            </Button>
          </Box>

          <ConsultantReviewNotice context="csv" />
          <Box
            role="group"
            aria-label="Exports"
            sx={{
              display: 'flex',
              flexWrap: 'wrap',
              alignItems: 'center',
              justifyContent: { xs: 'flex-start', sm: 'flex-end' },
              gap: 1,
              minWidth: 0,
              maxWidth: '100%',
              pt: 1,
              borderTop: '1px solid',
              borderColor: 'divider',
            }}
          >
            <Button
              size="small"
              variant="outlined"
              color="inherit"
              startIcon={<ExportIcon />}
              onClick={handleExportCsv}
              disabled={loading || filteredTransactions.length === 0}
              sx={toolbarActionButtonSx}
            >
              Export CSV
            </Button>
            <Button
              size="small"
              variant="contained"
              color="primary"
              startIcon={<ExportIcon fontSize="small" />}
              onClick={() => void handleExportAuditWorkbook()}
              disabled={loading || !hasOperationalData}
              sx={{
                ...toolbarActionButtonSx,
                px: 1,
                minWidth: 0,
              }}
            >
              Audit Excel
            </Button>
            <Tooltip title="Refresh operational data">
              <IconButton
                onClick={() => void loadData()}
                disabled={loading}
                aria-label="Refresh operational data"
                sx={{
                  width: 40,
                  height: 40,
                  flexShrink: 0,
                  borderRadius: 1,
                  border: '1px solid',
                  borderColor: 'divider',
                  color: 'text.secondary',
                }}
              >
                <RefreshIcon fontSize="small" />
              </IconButton>
            </Tooltip>
          </Box>
        </Box>
      </Box>

      <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }} flexWrap="wrap" useFlexGap>
        <Chip
          label="Unclassified only"
          variant={unclassifiedOnly ? 'filled' : 'outlined'}
          color={unclassifiedOnly ? 'primary' : 'default'}
          onClick={() => {
            setUnclassifiedOnly((prev) => !prev);
            setPage(0);
          }}
          clickable
        />
        <Chip
          label="Exceptions only"
          variant={exceptionsOnly ? 'filled' : 'outlined'}
          color={exceptionsOnly ? 'warning' : 'default'}
          onClick={() => {
            setExceptionsOnly((prev) => !prev);
            setPage(0);
          }}
          clickable
        />
        <Chip
          label={`Who owns this?${ownershipReviewCount > 0 ? ` (${ownershipReviewCount})` : ''}`}
          variant={ownershipReviewOnly ? 'filled' : 'outlined'}
          color={ownershipReviewOnly ? 'warning' : ownershipReviewCount > 0 ? 'warning' : 'default'}
          onClick={() => {
            setOwnershipReviewOnly((prev) => !prev);
            setPage(0);
          }}
          clickable
        />
        <Chip
          label={`Pending bill verification${provisionalInventoryCount > 0 ? ` (${provisionalInventoryCount})` : ''}`}
          variant={provisionalOnly ? 'filled' : 'outlined'}
          color={provisionalOnly ? 'info' : provisionalInventoryCount > 0 ? 'info' : 'default'}
          onClick={() => {
            setProvisionalOnly((prev) => !prev);
            setPage(0);
          }}
          clickable
        />
        <Button size="small" component={RouterLink} to="/compliance/export?section=product-pcf" variant="text">
          Product PCF setup
        </Button>
        {(dateFrom || dateTo || unclassifiedOnly || exceptionsOnly || ownershipReviewOnly || provisionalOnly || sourceFilter !== 'all' || searchInput) && (
          <Button
            size="small"
            onClick={() => {
              setSourceFilter('all');
              setUnclassifiedOnly(false);
              setExceptionsOnly(false);
              setOwnershipReviewOnly(false);
              setProvisionalOnly(false);
              setDateFrom('');
              setDateTo('');
              setSearchInput('');
              setPage(0);
            }}
          >
            Clear filters
          </Button>
        )}
      </Stack>

      {transportDoubleCountMonths.length > 0 && (
        <Alert severity="warning" sx={{ mb: 2 }} data-testid="transport-double-count-alert">
          {transportDoubleCountMonths.join(', ')} has both an accounting freight row and a separately entered travel row.
          Keep one activity record for that movement so Category 4 or 9 is not added again as Category 6 or 7.
        </Alert>
      )}

      {provisionalInventoryCount > 0 && (
        <Alert
          severity="info"
          sx={compactAlertSx}
          action={(
            <Button
              color="inherit"
              size="small"
              variant="outlined"
              onClick={() => {
                setProvisionalOnly(true);
                setPage(0);
              }}
              sx={provisionalReviewButtonSx}
            >
              Review now
            </Button>
          )}
        >
          {provisionalInventoryCount} bill transaction
          {provisionalInventoryCount === 1 ? ' is' : 's are'} provisional until you verify vendor, date, GSTIN, and invoice number.
        </Alert>
      )}

      {estimateScreening.exceedsThreshold ? (
        <Alert
          severity="error"
          sx={compactAlertSx}
          action={(
            <Button
              color="inherit"
              size="small"
              variant="outlined"
              onClick={() => openMissingDataDialog()}
              sx={missingDataButtonSx}
            >
              Add missing data
            </Button>
          )}
        >
          {estimateScreening.estimateOrMiscellaneousCount} of {estimateScreening.transactionCount} transactions ({estimateScreening.sharePercent}%) use an estimate or miscellaneous calculation, above the {estimateScreening.thresholdPercent}% limit. Add the activity quantity for an activity-based calculation, or the unit price for a spend-based calculation.
          {estimateRationaleDetails}
        </Alert>
      ) : estimateScreening.estimateOrMiscellaneousCount > 0 ? (
        <Alert
          severity="info"
          sx={compactAlertSx}
          action={(
            <Button
              color="inherit"
              size="small"
              variant="outlined"
              onClick={() => openMissingDataDialog()}
              sx={compactAlertButtonSx}
            >
              Add missing data
            </Button>
          )}
        >
          {estimateScreening.estimateOrMiscellaneousCount} of {estimateScreening.transactionCount} transactions on this view still need activity or spend data ({estimateScreening.sharePercent}%). The limit is under {estimateScreening.thresholdPercent}% of transactions. Confirmed quantities and unit prices are reused on later similar bills.
          {estimateRationaleDetails}
        </Alert>
      ) : null}

      {discrepancyRows.length > 0 && (
        <Alert severity="warning" sx={compactAlertSx} data-testid="calculation-discrepancies">
          <Stack
            direction="row"
            spacing={1}
            alignItems="center"
            justifyContent="space-between"
            useFlexGap
            flexWrap="wrap"
          >
            <Box sx={{ minWidth: 0 }}>
              <Typography variant="subtitle2" sx={{ fontWeight: 700 }}>
                Add the missing calculation details in this order
              </Typography>
              <Typography variant="body2">
                {discrepancyRows.length} discrepanc{discrepancyRows.length === 1 ? 'y' : 'ies'} on this page.
              </Typography>
            </Box>
            <Button
              size="small"
              color="inherit"
              variant="outlined"
              aria-expanded={discrepanciesOpen}
              aria-controls="calculation-discrepancy-list"
              onClick={() => setDiscrepanciesOpen((open) => !open)}
              sx={{ height: 32, minHeight: 32, px: 1.25, py: 0 }}
            >
              {discrepanciesOpen ? 'Hide details' : 'Show details'}
            </Button>
          </Stack>
          <Box id="calculation-discrepancy-list" hidden={!discrepanciesOpen}>
            <Box component="ol" sx={{ m: 0.5, pl: 2.5 }}>
              {discrepancyRows.slice(0, 6).map(({ txn, entry }) => (
                <Box component="li" key={`${txn._id}-${entry.id}`} sx={{ mb: 0.75 }}>
                  <Typography variant="body2">
                    <strong>{txn.description || txn.category}:</strong> {entry.request}
                  </Typography>
                  <Button
                    size="small"
                    color="inherit"
                    variant="outlined"
                    onClick={() => openDiscrepancy(txn, entry.field)}
                    sx={discrepancyDetailButtonSx}
                  >
                    Add this detail
                  </Button>
                </Box>
              ))}
            </Box>
            {discrepancyRows.length > 6 ? (
              <Typography variant="caption">
                {discrepancyRows.length - 6} more discrepancies follow the same order on each row.
              </Typography>
            ) : null}
          </Box>
        </Alert>
      )}

      {ownershipReviewCount > 0 && (
        <Alert
          severity="warning"
          sx={{ mb: 2 }}
          action={(
            <Button
              color="inherit"
              size="small"
              onClick={() => {
                setOwnershipReviewOnly(true);
                setPage(0);
              }}
            >
              Review now
            </Button>
          )}
        >
          {ownershipReviewCount} transport or fuel transaction
          {ownershipReviewCount === 1 ? '' : 's'} need a quick answer: is the vehicle or fuel for your own fleet or a third party?
          Open calculation details on each row to set owned vs outsourced.
        </Alert>
      )}

      {productCatalog.length === 0 && (
        <Alert severity="info" sx={{ mb: 2 }}>
          Add manufactured products under{' '}
          <Link component={RouterLink} to="/msme-profile">
            My company → Profile
          </Link>{' '}
          or{' '}
          <Link component={RouterLink} to="/operations">
            Operations
          </Link>{' '}
          to classify transactions at product level for ISO 14067 carbon footprints.
        </Alert>
      )}

      {success && (
        <Alert severity="success" sx={{ mb: 2 }} onClose={() => setSuccess(null)}>
          {success}
        </Alert>
      )}

      {error && (
        <Alert severity="error" sx={{ mb: 2 }} onClose={() => setError(null)}>
          {error}
        </Alert>
      )}

      {selectedIds.size > 0 && (
        <Stack direction="row" spacing={1} alignItems="center" sx={{ mb: 2 }} flexWrap="wrap" useFlexGap>
          <Typography variant="body2">{selectedIds.size} selected</Typography>
          <Button
            size="small"
            variant="contained"
            startIcon={<ClassifyIcon />}
            onClick={() => openClassifyDialog(Array.from(selectedIds))}
          >
            Classify selected
          </Button>
          <Button size="small" onClick={() => setSelectedIds(new Set())}>
            Clear selection
          </Button>
        </Stack>
      )}

      {loading ? (
        <LinearProgress />
      ) : !hasOperationalData && !searchQuery ? (
        <Alert severity="info">
          No operational transactions yet. Link an accounting connector (for example Tally or Zoho) or upload
          bills/invoices above to populate this table.
        </Alert>
      ) : searchQuery && transactions.length === 0 ? (
        <Alert severity="info">
          No transactions match that date or amount. Try a date like 01/03/2024 or an amount like 12000.
        </Alert>
      ) : (
        <>
          <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
            Newest imports are listed first.
          </Typography>
          {localFiltersActive && (
            <Typography variant="caption" color="text.secondary" display="block" sx={{ mb: 1 }}>
              Filters apply to this page only. The footer total is all operational transactions from the API.
            </Typography>
          )}
          <Box ref={setTablePaneNode} sx={{ minWidth: 0 }}>
          {filteredTransactions.length === 0 ? (
            <Alert severity="info" sx={{ mb: 2 }}>
              No transactions on this page match the selected filters.
            </Alert>
          ) : stackedActivityRows ? (
          <Stack spacing={1}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
              <Checkbox
                indeterminate={someVisibleSelected && !allVisibleSelected}
                checked={allVisibleSelected}
                onChange={handleToggleSelectAll}
                inputProps={{ 'aria-label': 'Select all transactions on this page' }}
              />
              <Typography variant="caption" color="text.secondary">Select all on this page</Typography>
            </Box>
            {filteredTransactions.map((txn) => {
              const boundary = resolveBoundary(txn);
              const ownership = resolveTransactionOwnership(txn);
              const ownershipReview = needsOwnershipReview(txn);
              const products = (txn.productAttribution?.assignedProducts || [])
                .map((item) => item.productName)
                .filter(Boolean)
                .join(', ');
              const estimateRow = isEstimateOrMiscellaneousTransaction(txn);
              const missingInput = resolveMissingCarbonInput(txn);
              const calculationTone = resolveCalculationTone(txn);
              const toneStyle = calculationTone ? CALCULATION_TONE_STYLE[calculationTone] : null;
              const toneLabel = calculationTone === 'estimate' && estimateRow.reason === 'miscellaneous_factor'
                ? 'Miscellaneous'
                : toneStyle?.label;
              const storedTier = txn.carbonFootprint?.dataQualityTier;
              const openWorksheet = () => {
                setDetailTxn(txn);
                setDetailOwnership(String((txn as { ownership?: string }).ownership || txn.metadata?.ownership || ''));
              };
              return (
                <Paper
                  key={txn._id}
                  variant="outlined"
                  sx={{
                    p: 1.25,
                    backgroundColor: selectedIds.has(txn._id)
                      ? 'action.selected'
                      : (calculationTone ? subtleToneBackground(calculationTone) : undefined),
                  }}
                >
                  <Box sx={{ display: 'flex', alignItems: 'flex-start', gap: 1, minWidth: 0 }}>
                    <Checkbox
                      checked={selectedIds.has(txn._id)}
                      onChange={() => handleToggleRow(txn._id)}
                      inputProps={{ 'aria-label': `Select transaction ${txn._id}` }}
                      sx={{ p: 0.5 }}
                    />
                    <Box sx={{ flex: 1, minWidth: 0 }}>
                      <Box sx={{ display: 'flex', justifyContent: 'space-between', gap: 1, alignItems: 'flex-start' }}>
                        <Box sx={{ minWidth: 0 }}>
                          <Typography variant="caption" color="text.secondary" component="div">Date</Typography>
                          <Typography variant="body2" sx={{ fontWeight: 600 }}>{sanitizeDisplayDate(txn.date)}</Typography>
                        </Box>
                        <Box sx={{ textAlign: 'right' }}>
                          <Typography variant="caption" color="text.secondary" component="div">Amount</Typography>
                          <Typography variant="body2" sx={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                            ₹{Number(txn.amount || 0).toLocaleString()}
                          </Typography>
                        </Box>
                      </Box>
                      <Stack spacing={0.5} sx={{ mt: 1, minWidth: 0 }}>
                        <RecordFact label="Source">
                          <Chip size="small" label={formatSourceLabel(txn)} variant="outlined" sx={wrapChipSx} />
                        </RecordFact>
                        <RecordFact label="Category">
                          <Typography variant="body2" component="span">{txn.category || 'other'}</Typography>
                          {toneStyle && (
                            <Chip size="small" variant="outlined" color={toneStyle.chipColor} label={toneLabel} sx={wrapChipSx} />
                          )}
                        </RecordFact>
                      </Stack>
                      <Box sx={{ mt: 1 }}>
                        <Typography variant="caption" color="text.secondary" component="div">CO₂e (kg)</Typography>
                        <ActivityEmissionValue txn={txn} calculationTone={calculationTone} toneLabel={toneLabel} />
                      </Box>
                      <Box sx={{ mt: 1 }}>
                        <ActivityRecordDetails
                          txn={txn}
                          boundary={boundary}
                          ownershipReview={ownershipReview}
                          ownership={ownership}
                          products={products}
                          storedTier={storedTier}
                        />
                      </Box>
                      <Box sx={{ mt: 1 }}>
                        <ActivityRowActions
                          txn={txn}
                          missingInput={Boolean(missingInput)}
                          descriptionUncertain={Boolean(missingInput?.descriptionUncertain)}
                          onOpenWorksheet={openWorksheet}
                          onOpenScope={() => {
                            setScopeTxn(txn);
                            setScopeAnswers({});
                          }}
                          onAddData={() => openMissingDataDialog(txn)}
                          onClassify={() => openClassifyDialog([txn._id])}
                        />
                      </Box>
                    </Box>
                  </Box>
                </Paper>
              );
            })}
          </Stack>
          ) : (
          <ScrollableTableContainer component={Paper} variant="outlined">
            <Table size="small">
              <TableHead>
                <TableRow>
                  <TableCell padding="checkbox" sx={activityHeadCellSx}>
                    <Checkbox
                      indeterminate={someVisibleSelected && !allVisibleSelected}
                      checked={allVisibleSelected}
                      onChange={handleToggleSelectAll}
                      inputProps={{ 'aria-label': 'Select all transactions on this page' }}
                    />
                  </TableCell>
                  <TableCell sx={activityHeadCellSx}>Date</TableCell>
                  <TableCell sx={activityHeadCellSx}>Source</TableCell>
                  {!HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI && <TableCell sx={activityHeadCellSx}>Description</TableCell>}
                  <TableCell sx={activityHeadCellSx}>Category</TableCell>
                  <TableCell align="right" sx={activityHeadCellSx}>Amount</TableCell>
                  <TableCell sx={activityHeadCellSx}>Classification</TableCell>
                  <TableCell sx={activityHeadCellSx}>Ownership</TableCell>
                  <TableCell sx={activityHeadCellSx}>Product(s)</TableCell>
                  <TableCell sx={activityHeadCellSx}>Data tier</TableCell>
                  <TableCell sx={activityHeadCellSx}>Inventory</TableCell>
                  <TableCell align="right" sx={activityHeadCellSx}>CO₂e (kg)</TableCell>
                  <TableCell align="right" sx={activityHeadCellSx}>Actions</TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {filteredTransactions.map((txn) => {
                  const boundary = resolveBoundary(txn);
                  const ownership = resolveTransactionOwnership(txn);
                  const ownershipReview = needsOwnershipReview(txn);
                  const products = (txn.productAttribution?.assignedProducts || [])
                    .map((item) => item.productName)
                    .filter(Boolean)
                    .join(', ');

                  const estimateRow = isEstimateOrMiscellaneousTransaction(txn);
                  const missingInput = resolveMissingCarbonInput(txn);
                  const calculationTone = resolveCalculationTone(txn);
                  const toneStyle = calculationTone ? CALCULATION_TONE_STYLE[calculationTone] : null;
                  const toneLabel = calculationTone === 'estimate' && estimateRow.reason === 'miscellaneous_factor'
                    ? 'Miscellaneous'
                    : toneStyle?.label;
                  const storedTier = txn.carbonFootprint?.dataQualityTier;
                  return (
                    <TableRow
                      key={txn._id}
                      hover
                      selected={selectedIds.has(txn._id)}
                      sx={calculationTone ? { backgroundColor: subtleToneBackground(calculationTone) } : undefined}
                    >
                      <TableCell padding="checkbox" sx={activityCellSx}>
                        <Checkbox
                          checked={selectedIds.has(txn._id)}
                          onChange={() => handleToggleRow(txn._id)}
                          inputProps={{ 'aria-label': `Select transaction ${txn._id}` }}
                        />
                      </TableCell>
                      <TableCell sx={{ ...activityCellSx, fontWeight: 600, whiteSpace: 'nowrap' }}>{sanitizeDisplayDate(txn.date)}</TableCell>
                      <TableCell sx={activityCellSx}>
                        <Chip size="small" label={formatSourceLabel(txn)} variant="outlined" />
                      </TableCell>
                      {!HIDE_DOCUMENTS_SENSITIVE_INPUTS_UI && (
                        <TableCell sx={activityCellSx}>
                          <Typography variant="body2" sx={wrapTextSx}>{txn.description || '—'}</Typography>
                        </TableCell>
                      )}
                      <TableCell sx={activityCellSx}>
                        <Box sx={{ display: 'flex', flexWrap: 'wrap', alignItems: 'center', gap: 0.5, ...wrapTextSx }}>
                          <Typography variant="body2" component="span">{txn.category || 'other'}</Typography>
                          {toneStyle && (
                            <Chip
                              size="small"
                              variant="outlined"
                              color={toneStyle.chipColor}
                              label={toneLabel}
                            />
                          )}
                        </Box>
                      </TableCell>
                      <TableCell align="right" sx={{ ...activityCellSx, fontWeight: 600, fontVariantNumeric: 'tabular-nums', whiteSpace: 'nowrap' }}>
                        ₹{Number(txn.amount || 0).toLocaleString()}
                      </TableCell>
                      <TableCell sx={activityCellSx}>
                        <Chip
                          size="small"
                          variant="outlined"
                          color={boundary === 'product' ? 'secondary' : 'primary'}
                          label={boundary === 'product' ? 'Manufactured product' : 'Company'}
                        />
                      </TableCell>
                      <TableCell sx={activityCellSx}>
                        {ownershipReview ? (
                          <Chip
                            size="small"
                            color="warning"
                            variant="outlined"
                            label={MSME_SIMPLIFIED_ACTION_LABELS.ownershipNeedsAnswer}
                          />
                        ) : ownership ? (
                          <Chip size="small" variant="outlined" label={formatOwnershipLabel(ownership)} />
                        ) : (
                          '—'
                        )}
                      </TableCell>
                      <TableCell sx={activityCellSx}>
                        <Typography variant="body2" sx={wrapTextSx}>{products || '—'}</Typography>
                      </TableCell>
                      <TableCell sx={activityCellSx}>
                        {storedTier ? (
                          <Chip
                            size="small"
                            variant="outlined"
                            color={tierChipColor(storedTier)}
                            label={labelDataQualityTier(storedTier)}
                          />
                        ) : (
                          '—'
                        )}
                      </TableCell>
                      <TableCell sx={activityCellSx}>
                        {isProvisionalInventoryTransaction(txn) ? (
                          <Chip size="small" color="info" variant="outlined" label="Pending verification" />
                        ) : (
                          <Chip size="small" variant="outlined" label="Confirmed" />
                        )}
                      </TableCell>
                      <TableCell align="right" sx={activityCellSx}>
                        <Box sx={{ width: 180, maxWidth: '100%', ml: 'auto' }}>
                          <ActivityEmissionValue txn={txn} calculationTone={calculationTone} toneLabel={toneLabel} />
                        </Box>
                      </TableCell>
                      <TableCell align="right" sx={activityCellSx}>
                        <ActivityRowActions
                          txn={txn}
                          missingInput={Boolean(missingInput)}
                          descriptionUncertain={Boolean(missingInput?.descriptionUncertain)}
                          onOpenWorksheet={() => {
                            setDetailTxn(txn);
                            setDetailOwnership(String((txn as { ownership?: string }).ownership || txn.metadata?.ownership || ''));
                          }}
                          onOpenScope={() => {
                            setScopeTxn(txn);
                            setScopeAnswers({});
                          }}
                          onAddData={() => openMissingDataDialog(txn)}
                          onClassify={() => openClassifyDialog([txn._id])}
                        />
                      </TableCell>
                    </TableRow>
                  );
                })}
              </TableBody>
            </Table>
          </ScrollableTableContainer>
          )}
          </Box>
          <TablePagination
            component="div"
            sx={{
              '& .MuiTablePagination-toolbar': {
                flexWrap: { xs: 'wrap', sm: 'nowrap' },
                justifyContent: { xs: 'flex-end', sm: 'flex-start' },
              },
              '& .MuiTablePagination-spacer': {
                display: { xs: 'none', sm: 'flex' },
              },
            }}
            rowsPerPageOptions={ROWS_PER_PAGE_OPTIONS}
            count={paginationTotal}
            rowsPerPage={rowsPerPage}
            page={page}
            onPageChange={(_event, newPage) => {
              void fetchTransactions(newPage, rowsPerPage);
            }}
            onRowsPerPageChange={(event) => {
              const nextLimit = parseInt(event.target.value, 10);
              void fetchTransactions(0, nextLimit);
            }}
            backIconButtonProps={{ disabled: loading || page === 0 }}
            nextIconButtonProps={{ disabled: loading || page >= Math.max(0, Math.ceil(paginationTotal / rowsPerPage) - 1) }}
            SelectProps={{ disabled: loading }}
          />
        </>
      )}

      <UncertaintyClarificationAgentDialog
        open={agentOpen}
        loading={agentLoading}
        saving={agentSaving}
        error={agentError}
        questions={agentQuestions}
        identifiedPrices={agentIdentified}
        onClose={() => setAgentOpen(false)}
        onSubmitGroup={(entries) => void saveUncertaintyGroup(entries)}
        onUndoIdentified={(row) => void undoIdentifiedPrice(row)}
      />

      <Dialog
        open={Boolean(inputTxn)}
        onClose={() => setInputTxn(null)}
        maxWidth="sm"
        fullWidth
        fullScreen={worksheetFullScreen}
        scroll="paper"
      >
        <DialogTitle sx={{ wordBreak: 'break-word' }}>
          {inputStep === 'bill'
            ? 'Upload the bill'
            : inputStep === 'clarify'
              ? (inputPrompt?.clarification?.title || 'Clarify this transaction')
              : (inputPrompt?.title || 'Add data for the carbon calculation')}
        </DialogTitle>
        <DialogContent>
          {inputTxn && inputPrompt && (
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Box>
                <Typography variant="subtitle1" sx={{ fontWeight: 700, wordBreak: 'break-word' }}>
                  {inputTxn.description || inputTxn.category}
                </Typography>
                <Typography variant="body2" sx={{ fontWeight: 600, fontVariantNumeric: 'tabular-nums' }}>
                  ₹{Number(inputTxn.amount || 0).toLocaleString()}
                </Typography>
              </Box>
              <Alert severity={isBillUploadEnabled() ? 'info' : 'warning'}>
                {inputStep === 'bill'
                  ? 'The description does not say what this transaction is. Upload the bill so the activity can be read from it.'
                  : inputStep === 'clarify'
                    ? (inputPrompt.clarification?.helper
                      || 'The bill is not uploaded. Name the activity and enter the quantity.')
                    : isBillUploadEnabled()
                      ? (
                        <>
                          Upload the bill and add the activity so this row enters the inventory
                          {inputPrompt.spend ? ', or enter a unit price for a spend-based screening figure' : ''}.
                          {' '}The bill is checked against the missing quantity, unit, amount, date, and vendor.
                        </>
                      )
                      : (
                        <>
                          {BILL_UPLOAD_DISABLED_MESSAGE}
                          {' '}Enter the quantity and unit so this row enters the inventory
                          {inputPrompt.spend ? ', or enter a unit price for a spend-based screening figure' : ''}.
                        </>
                      )}
              </Alert>
              {inputStep === 'clarify' && inputPrompt.clarification?.example && (
                <Typography variant="body2" color="text.secondary">
                  {`Example: ${inputPrompt.clarification.example}`}
                </Typography>
              )}
              {inputStep === 'clarify'
                && !(Array.isArray(inputPrompt.activity?.fields) && inputPrompt.activity.fields.length > 0)
                && inputPrompt.id !== 'activity_quantity_missing'
                && inputPrompt.id !== 'service_count_missing' && (
                <TextField
                  size="small"
                  label={inputPrompt.clarification?.question || 'What is this transaction?'}
                  value={inputClarification}
                  onChange={(event) => setInputClarification(event.target.value)}
                  placeholder={inputPrompt.clarification?.example || ''}
                  fullWidth
                  required
                />
              )}
              {inputStep !== 'bill' && <Box sx={dialogSectionSx}>
                <Typography variant="subtitle2">Calculation basis</Typography>
                <FormControl fullWidth size="small">
                  <InputLabel id="carbon-input-basis-label">Calculation</InputLabel>
                  <Select
                    labelId="carbon-input-basis-label"
                    label="Calculation"
                    value={inputBasis}
                    onChange={(event) => setInputBasis(event.target.value as 'activity' | 'spend')}
                  >
                    {inputPrompt.activity && <MenuItem value="activity">Activity-based</MenuItem>}
                    {inputPrompt.spend && <MenuItem value="spend">Spend-based</MenuItem>}
                  </Select>
                </FormControl>
              </Box>}
              {inputStep !== 'bill' && inputBasis === 'activity' && inputPrompt.activity && (
                <Box sx={dialogSectionSx}>
                  <Typography variant="subtitle2">Quantity and unit</Typography>
                  <Typography variant="body2">{inputPrompt.activity.helper}</Typography>
                  {Array.isArray(inputPrompt.activity.fields) && inputPrompt.activity.fields.map((field: {
                    id: string;
                    label: string;
                    metadataField: string;
                    kind?: 'choice' | 'number' | 'text';
                    options?: Array<{ value: string; label: string }>;
                  }) => (
                    field.kind === 'choice' ? (
                      <FormControl key={field.id} fullWidth size="small">
                        <InputLabel id={`${field.id}-label`}>{field.label}</InputLabel>
                        <Select
                          labelId={`${field.id}-label`}
                          label={field.label}
                          value={inputExtras[field.metadataField] || ''}
                          onChange={(event) => setInputExtras((current) => ({
                            ...current,
                            [field.metadataField]: String(event.target.value)
                          }))}
                        >
                          <MenuItem value="" disabled>Select</MenuItem>
                          {(field.options || []).map((option) => (
                            <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                          ))}
                        </Select>
                      </FormControl>
                    ) : (
                      <TextField
                        key={field.id}
                        size="small"
                        label={field.label}
                        type={field.kind === 'number' ? 'number' : 'text'}
                        value={inputExtras[field.metadataField] || ''}
                        onChange={(event) => setInputExtras((current) => ({
                          ...current,
                          [field.metadataField]: event.target.value
                        }))}
                        fullWidth
                      />
                    )
                  ))}
                  {inputPrompt.activity.requireMaterialName && (
                    <TextField
                      size="small"
                      label="Material or activity name"
                      value={inputMaterial}
                      onChange={(event) => setInputMaterial(event.target.value)}
                      fullWidth
                    />
                  )}
                  {inputPrompt.activity.requireAirports && (
                    <>
                      <TextField
                        size="small"
                        label="Origin airport"
                        value={inputOrigin}
                        onChange={(event) => setInputOrigin(event.target.value.toUpperCase())}
                        placeholder="BLR"
                        fullWidth
                        inputProps={{ maxLength: 3 }}
                      />
                      <TextField
                        size="small"
                        label="Destination airport"
                        value={inputDestination}
                        onChange={(event) => setInputDestination(event.target.value.toUpperCase())}
                        placeholder="DEL"
                        fullWidth
                        inputProps={{ maxLength: 3 }}
                      />
                    </>
                  )}
                  <TextField
                    size="small"
                    label={inputPrompt.activity.quantityLabel}
                    type="number"
                    value={inputQuantity}
                    onChange={(event) => setInputQuantity(event.target.value)}
                    fullWidth
                    inputProps={{ min: 0, step: 'any' }}
                  />
                  {Array.isArray(inputPrompt.activity.extraFields) && inputPrompt.activity.extraFields.length > 0 && (
                    <>
                      <Typography variant="body2">
                        If the bill does not state the activity, fill the missing fields. Weight and distance become tonne-km. Passengers and kilometres become passenger-km when that is the unit.
                      </Typography>
                      {inputPrompt.activity.extraFields.map((field: { id: string; label: string; metadataField: string }) => (
                        <TextField
                          key={field.id}
                          size="small"
                          label={field.label}
                          type="number"
                          value={inputExtras[field.metadataField] || ''}
                          onChange={(event) => setInputExtras((current) => ({
                            ...current,
                            [field.metadataField]: event.target.value
                          }))}
                          fullWidth
                          inputProps={{ min: 0, step: 'any' }}
                        />
                      ))}
                    </>
                  )}
                  <FormControl fullWidth size="small">
                    <InputLabel id="carbon-input-unit-label">Unit</InputLabel>
                    <Select
                      labelId="carbon-input-unit-label"
                      label="Unit"
                      value={inputUnit}
                      onChange={(event) => setInputUnit(event.target.value)}
                    >
                      {inputPrompt.activity.unitOptions.map((unit: string) => (
                        <MenuItem key={unit} value={unit}>{unit}</MenuItem>
                      ))}
                    </Select>
                  </FormControl>
                </Box>
              )}
              {(inputStep === 'bill' || inputStep === 'fields') && inputBasis === 'activity' && inputPrompt.activity && isBillUploadEnabled() && (
                <Box sx={dialogSectionSx}>
                  <Typography variant="subtitle2">Bill evidence</Typography>
                  <Alert severity="warning">
                    Upload the bill as evidence. Its quantity, unit, amount, date, and vendor are checked against the missing activity.
                  </Alert>
                  <Button variant="outlined" component="label" disabled={readingBill} sx={dialogActionSx}>
                    {readingBill ? 'Reading bill…' : (inputBill ? inputBill.name : 'Upload bill')}
                    <input
                      hidden
                      type="file"
                      accept=".pdf,.png,.jpg,.jpeg,.webp,application/pdf,image/*"
                      aria-label="Upload the bill as evidence"
                      onChange={(event) => {
                        const file = event.target.files?.[0];
                        if (file) void readBillAgainstMissingInputs(file);
                      }}
                    />
                  </Button>
                  <Typography variant="caption" color="text.secondary">
                    PDF, PNG, JPG, JPEG, WEBP, or another image.
                  </Typography>
                  {!inputBill && !evidenceDocumentId && inputStep === 'fields' && (
                    <Typography variant="caption" color="warning.main">
                      Upload the bill to enable Save and recalculate.
                    </Typography>
                  )}
                  {inputStep === 'bill' && !inputBill && !evidenceDocumentId && (
                    <Button
                      variant="text"
                      onClick={() => setInputStep('clarify')}
                      sx={dialogActionSx}
                    >
                      The bill is not uploaded
                    </Button>
                  )}
                  {billChecks.length > 0 && (
                    <Stack spacing={0.5}>
                      {billChecks.map((check) => (
                        <Typography
                          key={check.field}
                          variant="body2"
                          sx={{
                            px: 1,
                            py: 0.5,
                            borderLeft: '2px solid',
                            borderColor: check.status === 'match' ? 'success.main' : 'warning.main',
                            overflowWrap: 'anywhere',
                          }}
                        >
                          {check.status === 'match' ? 'Match' : 'Check'}: {check.message}
                        </Typography>
                      ))}
                    </Stack>
                  )}
                </Box>
              )}
              {inputStep !== 'bill' && inputBasis === 'spend' && inputPrompt.spend && (
                <Box sx={dialogSectionSx}>
                  <Typography variant="subtitle2">Unit price</Typography>
                  <Typography variant="body2">{inputPrompt.spend.helper}</Typography>
                  <TextField
                    size="small"
                    label={inputPrompt.spend.label}
                    type="number"
                    value={inputPrice}
                    onChange={(event) => setInputPrice(event.target.value)}
                    fullWidth
                    inputProps={{ min: 0, step: 'any' }}
                  />
                </Box>
              )}
            </Stack>
          )}
        </DialogContent>
        <DialogActions sx={dialogFooterSx}>
          <Button onClick={() => setInputTxn(null)} disabled={savingInput} sx={dialogActionSx}>Cancel</Button>
          <Button
            variant="contained"
            sx={dialogActionSx}
            onClick={() => void saveMissingCarbonInput()}
            disabled={savingInput || readingBill || inputStep === 'bill' || (isBillUploadEnabled() && inputStep === 'fields' && inputBasis === 'activity' && !inputBill && !evidenceDocumentId)}
          >
            {savingInput ? 'Saving…' : 'Save and recalculate'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={classifyDialogOpen} onClose={() => setClassifyDialogOpen(false)} maxWidth="sm" fullWidth>
        <DialogTitle>
          Classify {classifyTargetIds.length} transaction{classifyTargetIds.length === 1 ? '' : 's'}
        </DialogTitle>
        <DialogContent>
          <Stack spacing={2} sx={{ mt: 1 }}>
            <Alert severity="info">
              You are about to classify {classifyTargetIds.length} transaction
              {classifyTargetIds.length === 1 ? '' : 's'} as{' '}
              <strong>
                {classifyBoundary === 'product' ? 'manufactured product' : 'company (organizational)'}
              </strong>
              {classifyBoundary === 'product' && classifyProducts.length > 0
                ? ` — ${classifyProducts.join(', ')}`
                : ''}
              . Currently: {classifyPreviewSummary.companyCount} company,{' '}
              {classifyPreviewSummary.productCount} product.
            </Alert>
            <FormControl fullWidth>
              <InputLabel id="classification-boundary-label">Emission boundary</InputLabel>
              <Select
                labelId="classification-boundary-label"
                label="Emission boundary"
                value={classifyBoundary}
                onChange={(event) =>
                  setClassifyBoundary(event.target.value as 'company' | 'product')
                }
              >
                <MenuItem value="company">Company (organizational GHG inventory)</MenuItem>
                <MenuItem value="product">Manufactured product (product carbon footprint)</MenuItem>
              </Select>
            </FormControl>

            {classifyBoundary === 'product' && (
              <FormControl fullWidth>
                <InputLabel id="classification-products-label">Manufactured product(s)</InputLabel>
                <Select
                  labelId="classification-products-label"
                  label="Manufactured product(s)"
                  multiple
                  value={classifyProducts}
                  onChange={(event) => {
                    const value = event.target.value;
                    setClassifyProducts(typeof value === 'string' ? value.split(',') : value);
                  }}
                  renderValue={(selected) => (
                    <Box sx={{ display: 'flex', flexWrap: 'wrap', gap: 0.5 }}>
                      {selected.map((value) => (
                        <Chip key={value} label={value} size="small" />
                      ))}
                    </Box>
                  )}
                >
                  {productCatalog.map((product) => (
                    <MenuItem key={product.productId} value={product.productName}>
                      {product.productName}
                    </MenuItem>
                  ))}
                </Select>
              </FormControl>
            )}

            <TextField
              label="Reason (optional)"
              multiline
              minRows={2}
              value={classifyReason}
              onChange={(event) => setClassifyReason(event.target.value)}
              placeholder="Why this transaction belongs to the company or a specific manufactured product"
            />
          </Stack>
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setClassifyDialogOpen(false)} disabled={classifying}>
            Cancel
          </Button>
          <Button variant="contained" onClick={() => void handleApplyClassification()} disabled={classifying}>
            {classifying ? 'Saving…' : 'Apply classification'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog open={Boolean(scopeTxn)} onClose={() => setScopeTxn(null)} maxWidth="sm" fullWidth>
        <DialogTitle>Classify this bill as Scope 1 or Scope 3</DialogTitle>
        <DialogContent>
          {scopeTxn && (
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Typography variant="body2" color="text.secondary">
                {scopeTxn.description || scopeTxn.category} · ₹{Number(scopeTxn.amount || 0).toLocaleString()}
              </Typography>
              <Alert severity="info">
                {scopeTxn.scopeClassification?.basis
                  || 'The uploaded row is missing the fields needed to separate direct combustion from contractor activity.'}
              </Alert>
              {(scopeTxn.scopeClassification?.questions || []).map((item) => (
                <Box key={item.id}>
                  <Typography variant="subtitle2">{item.prompt}</Typography>
                  {item.detail ? (
                    <Typography variant="caption" color="text.secondary" sx={{ display: 'block', mb: 1 }}>
                      {item.detail}
                    </Typography>
                  ) : null}
                  {item.inputType === 'number' ? (
                    <TextField
                      fullWidth
                      size="small"
                      type="number"
                      label={item.prompt}
                      value={scopeAnswers[item.id] || ''}
                      onChange={(event) => setScopeAnswers((prev) => ({ ...prev, [item.id]: event.target.value }))}
                      inputProps={{ min: 0, 'data-testid': `scope-answer-${item.id}` }}
                    />
                  ) : (
                    <FormControl fullWidth size="small">
                      <InputLabel id={`scope-${item.id}`}>{item.prompt}</InputLabel>
                      <Select
                        labelId={`scope-${item.id}`}
                        label={item.prompt}
                        value={scopeAnswers[item.id] || ''}
                        onChange={(event) => setScopeAnswers((prev) => ({ ...prev, [item.id]: String(event.target.value) }))}
                      >
                        {(item.options || []).map((option) => (
                          <MenuItem key={option.value} value={option.value}>{option.label}</MenuItem>
                        ))}
                      </Select>
                    </FormControl>
                  )}
                </Box>
              ))}
            </Stack>
          )}
        </DialogContent>
        <DialogActions>
          <Button onClick={() => setScopeTxn(null)} disabled={savingScope}>Cancel</Button>
          <Button
            variant="contained"
            disabled={savingScope || !scopeTxn}
            onClick={async () => {
              if (!scopeTxn) return;
              setSavingScope(true);
              setError(null);
              try {
                const answers: Record<string, string | number> = {};
                Object.entries(scopeAnswers).forEach(([key, value]) => {
                  answers[key] = key === 'activity_quantity' ? Number(value) : value;
                });
                await ApiService.classifyTransactionScope(scopeTxn._id, answers);
                await loadData();
                setScopeTxn(null);
                setSuccess('Scope saved. Emissions were recalculated from the quantity and boundary you confirmed.');
              } catch (err: unknown) {
                setError(err instanceof Error ? err.message : 'Unable to classify this transaction');
              } finally {
                setSavingScope(false);
              }
            }}
          >
            {savingScope ? 'Calculating…' : 'Save and calculate'}
          </Button>
        </DialogActions>
      </Dialog>

      <Dialog
        open={Boolean(detailTxn)}
        onClose={() => setDetailTxn(null)}
        maxWidth="lg"
        fullWidth
        fullScreen={worksheetFullScreen}
        scroll="paper"
        sx={{
          '& .MuiDialog-paper': {
            overflow: 'hidden',
            display: 'flex',
            flexDirection: 'column',
            ...(worksheetFullScreen
              ? { height: '100%', maxHeight: '100%' }
              : { maxHeight: 'calc(100% - 64px)' }),
          },
        }}
      >
        <DialogTitle
          component="div"
          sx={{
            flex: '0 0 auto',
            borderBottom: '1px solid',
            borderColor: 'divider',
            minWidth: 0,
          }}
        >
          <Typography variant="h6" component="h2">
            Carbon calculation worksheet
          </Typography>
          {detailTxn && (
            <>
              <Typography
                variant="body2"
                sx={{
                  mt: 0.75,
                  fontWeight: 600,
                  lineHeight: 1.45,
                  whiteSpace: 'normal',
                  overflowWrap: 'break-word',
                }}
              >
                {detailTxn.description || detailTxn.category}
              </Typography>
              <Typography
                variant="body2"
                color="text.secondary"
                sx={{
                  display: 'block',
                  mt: 0.5,
                  fontWeight: 600,
                  lineHeight: 1.4,
                  fontVariantNumeric: 'tabular-nums',
                }}
              >
                ₹{Number(detailTxn.amount || 0).toLocaleString()}
              </Typography>
            </>
          )}
        </DialogTitle>
        <DialogContent
          sx={{
            flex: '1 1 auto',
            minHeight: 0,
            overflowX: 'hidden',
            overflowY: 'auto',
            '.MuiDialogTitle-root + &.MuiDialogContent-root': {
              paddingTop: '12px',
            },
          }}
        >
          {detailTxn && (
            <TransactionCalculationDetails
              key={detailTxn._id}
              footprint={{
                ...(detailTxn.carbonFootprint || {}),
                calculationDiscrepancies: collectCalculationDiscrepancies(detailTxn),
              }}
              transactionType={detailTxn.transactionType}
              category={detailTxn.category}
              subcategory={detailTxn.subcategory}
              ownership={detailOwnership}
              amount={detailTxn.amount}
              quantity={detailTxn.quantity}
              unit={detailTxn.unit}
              description={detailTxn.description}
            />
          )}
        </DialogContent>
        <DialogActions
          sx={{
            ...worksheetDialogFooterSx,
            justifyContent: 'flex-end',
          }}
        >
          {worksheetOwnershipEditable && (
            <Box
              sx={{
                display: 'flex',
                flexWrap: 'wrap',
                alignItems: 'center',
                gap: 1,
                flex: '1 1 280px',
                minWidth: 0,
                p: 1,
                border: '1px solid',
                borderColor: 'divider',
                borderRadius: 1,
              }}
            >
              <FormControl size="small" sx={{ flex: '1 1 220px', minWidth: { xs: '100%', sm: 220 } }}>
                <InputLabel id="ownership-label">Asset ownership (Scope 1 vs 3)</InputLabel>
                <Select
                  labelId="ownership-label"
                  label="Asset ownership (Scope 1 vs 3)"
                  value={detailOwnership}
                  onChange={(event) => setDetailOwnership(event.target.value)}
                  sx={{ '& .MuiSelect-select': { overflow: 'hidden', textOverflow: 'ellipsis' } }}
                >
                  <MenuItem value="">Unknown (default Scope 3)</MenuItem>
                  <MenuItem value="owned">Owned / company fleet (Scope 1)</MenuItem>
                  <MenuItem value="controlled">Controlled asset (Scope 1)</MenuItem>
                  <MenuItem value="outsourced">Outsourced / third party (Scope 3)</MenuItem>
                  <MenuItem value="third_party">Third-party logistics (Scope 3)</MenuItem>
                </Select>
              </FormControl>
              <Button
                variant="contained"
                sx={worksheetDialogActionSx}
                disabled={savingOwnership}
                onClick={async () => {
                  if (!detailTxn?._id) return;
                  setSavingOwnership(true);
                  try {
                    await ApiService.updateTransaction(detailTxn._id, { ownership: detailOwnership });
                    await loadData();
                    setDetailTxn(null);
                    setSuccess('Ownership updated — emissions recalculated.');
                  } catch (err: unknown) {
                    setError(err instanceof Error ? err.message : 'Failed to update ownership');
                  } finally {
                    setSavingOwnership(false);
                  }
                }}
              >
                {savingOwnership ? 'Saving…' : 'Save ownership'}
              </Button>
            </Box>
          )}
          <Button onClick={() => setDetailTxn(null)} sx={worksheetDialogActionSx}>Close</Button>
        </DialogActions>
      </Dialog>
    </Paper>
  );
};

export default OperationalTransactionsTable;
